  window.STUDY_DATA.questions.push({"id": "e01", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "The word “configure” is closest in meaning to ____.", "options": ["delete", "set up", "borrow", "break"], "answer": "set up", "pitfalls": ["IT词汇：set up同义"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】set up 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The word “configure” is closest in meaning to ______。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭", "analysis": "【审题】题干问 configure 的最接近词义，属词义辨析题。configure 是 IT 常用词，意为“配置、设置（系统/软件/设备）”。四个选项都是动词原形，只需比词义。 【语法点/词汇】configure = set up（设置、安装、配置）；delete 删除；borrow 借入；break 打破、损坏。同义替换：configure ↔ set up / adjust settings。 【步骤】① 先回忆 configure 的核心义：把参数、选项设好，使系统可用。② 逐一代入：A delete（删除）——意思相反/无关，错。③ B set up（建立、设置）——与“配置”同义，对。④ C borrow（借）——完全不相关，错。⑤ D break（打破）——无关，错。⑥ 验证：configure a computer = set up a computer，成立。 【答案】B. set up。 【易错】易被中文“配置”字面带偏，误选与“删除/清空”相关的 delete；也不要把 configure 和 confirm（确认）混淆。 【口诀/模板句】configure 就是 set up，配置等于设置；词义题先定核心义，再排除不沾边选项。", "steps": ["【秒懂考点】词义辨析：configure = 设置、配置", "【第一步：题干】configure最接近哪个意思？", "【第二步】configure（配置）就是set up（设置、安装）", "【第三步】delete删除、borrow借、break弄坏，都不对", "【答案】选set up"]});
  window.STUDY_DATA.questions.push({"id": "e02", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "Please fill ____ the form before submission.", "options": ["in", "on", "at", "for"], "answer": "in", "pitfalls": ["fill in固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】in 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Please fill ______ the form before submission.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答", "analysis": "【审题】题干：Please fill ______ the form before submission.（提交前请填表。）空格在 fill 与 the form 之间，考固定搭配的介词/副词。 【语法点/词汇】fill in / fill out 均可表示“填写表格”；fill in 强调填入空白处，英式更常用；fill out 强调填完整张表。fill on、fill at、fill for 均不与 form 构成“填表”义。fill for 可表示“代替”，fill up 是“装满”。 【步骤】① 识别搭配：fill + 宾语（form）需要介词/副词构成短语。② 填表固定说 fill in the form 或 fill out the form。③ 选项中只有 in 是正确的介词。④ A. in ✓。⑤ B. on——fill on 不表示填表，错。⑥ C. at——fill at 无此搭配，错。⑦ D. for——fill for = 代替某人，与表格无关，错。 【答案】A. in。 【易错】把 fill in 和 fill in for（代替）混淆；或误以为“在表格上填”就用 on，其实 on the form 作地点状语时才对（write on the form），fill 必须配 in/out。 【口诀/模板句】fill in / fill out the form = 填表；fill up 装满，fill for 代班，fill in 填空。", "steps": ["【秒懂考点】固定搭配：fill in = 填写", "【第一步：题干】提交前请填写表格", "【第二步】fill in是固定短语，in表示填入", "【第三步】fill on/at/for都不搭配", "【答案】选in"]});
  window.STUDY_DATA.questions.push({"id": "e04", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "She ____ in this company for five years sinshe graduated.", "options": ["worked", "has worked", "had worked", "works"], "answer": "has worked", "pitfalls": ["for+时间段完成时"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】has worked 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：She ______ in this company for five years sinsh。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/", "analysis": "【审题】题干：She ______ in this company for five years sinshe graduated. 出现 for five years（持续时间段）和 sinshe graduated（自从毕业），时间标志指向“从过去延续到现在”。 【语法点/词汇】现在完成时：have/has + 过去分词，表示动作从过去开始持续到现在，或对现在有影响。for + 时间段，sin+ 过去时间点/从句，是现在完成时的经典标志。第三人称单数用 has。 【步骤】① 圈时间标志：for five years + since… → 现在完成时。② 结构：has worked（she 是三单）。③ A. worked 一般过去时——只表示过去，不体现“到现在五年”，错。④ B. has worked ✓。⑤ C. had worked 过去完成时——需要“过去的过去”，本句无参照过去点，错。⑥ D. works 一般现在时——不能与 for five years 连用表持续，错。⑦ 回译：她毕业以来已在这家公司工作五年。 【答案】B. has worked。 【易错】看到 sin就想过去时；或三单忘了 has 用 have；或把 had worked 当“更完成”误选。 【口诀/模板句】for sin配完成，have/has + 过去分；三单 has 其余 have，过去完成要“过去的过去”。", "steps": ["【秒懂考点】现在完成时：for+时间段，持续到现在", "【第一步：题干】她毕业以来在这家公司工作了五年", "【第二步】for five years + since，持续到现在，用现在完成时", "【第三步】has worked（have/has+过去分词）", "【第四步】worked过去式、had worked过去完成、works现在时，都不符合", "【答案】选has worked"]});
  window.STUDY_DATA.questions.push({"id": "e06", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "The project ____ by our team next month.", "options": ["will complete", "will be completed", "is completed", "has completed"], "answer": "will be completed", "pitfalls": ["被动结构"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】will be completed 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：The project ______ by our team next month.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语", "analysis": "【审题】题干：The project ______ by our team next month. 有 by our team（被我们团队）和 next month（下月），说明是将来时的被动语态。 【语法点/词汇】一般将来时被动：will be + 过去分词。by + 施动者是被动标志；next month 是将来时间标志。complete 完成，及物动词，project 是“被完成”的对象。 【步骤】① 看时间 next month → 将来时（will）。② 看 by our team → 被动（be + done）。③ 合并：will be completed。④ A. will complete——主动“将完成”，项目不能自己完成自己，错。⑤ B. will be completed ✓。⑥ C. is completed——一般现在时被动，与 next month 不符，错。⑦ D. has completed——现在完成主动，错。 【答案】B. will be completed。 【易错】只看 by 就写 be done，忘了 will；或把 complete 当不及物；或误选 will complete，忽略主语是动作承受者。 【口诀/模板句】by + 施动者是被动，next + 时间用 will；将来被动 will be done，主语承受记心上。", "steps": ["【秒懂考点】被动语态：项目被完成", "【第一步：题干】项目将在下个月被我们团队完成", "【第二步】project和complete是被动关系，将来时被动", "【第三步】will be completed（will be+过去分词）", "【第四步】will complete主动、is completed现在被动、has completed主动", "【答案】选will be completed"]});
  window.STUDY_DATA.questions.push({"id": "e09", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "The devi____ we tested yesterday is used for mobile development.", "options": ["who", "which", "where", "what"], "answer": "which", "pitfalls": ["物which"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】which 【考点】从句 【一步步怎么算】 ① 句子/题干：The devi______ we tested yesterday is used for 。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确", "analysis": "【审题】题干：The devi______ we tested yesterday is used for mobile development. 空格引导定语从句，先行词是 the device（物），从句 we tested yesterday 缺宾语。 【语法点/词汇】定语从句关系词：who/whom/that/which 代人/物，where 表地点（从句不缺主宾），what 不能引导定语从句。物作先行词且作宾语 → which/that。本题选项只有 which。 【步骤】① 找先行词：the device（物）。② 分析从句成分：we tested yesterday——tested 缺宾语（tested what? the device）。③ 物 + 作宾语 → which（或 that）。④ A. who——只能指人，错。⑤ B. which ✓。⑥ C. where——表地点状语，从句不能缺主宾时才用，此处缺宾语，错。⑦ D. what——不引导定语从句，错。 【答案】B. which。 【易错】devi是设备但被当成“地点”用 where；或不知 what 不能做定语从句关系词；缺宾语却选了作状语的 where。 【口诀/模板句】人 who 物 which，缺宾 which/that 补；where 只管地点状，what 不进定语从。", "steps": ["【秒懂考点】定语从句：which指代物", "【第一步：题干】我们昨天测试的设备用于移动开发", "【第二步】先行词device是物，在从句中作宾语，用which", "【第三步】who指人，where指地点，what不引导定语从句", "【答案】选which"]});
  window.STUDY_DATA.questions.push({"id": "e10", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "I don't know ____ he will come tomorrow.", "options": ["that", "what", "whether", "which"], "answer": "whether", "pitfalls": ["是否whether"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】whether 【考点】从句 【一步步怎么算】 ① 句子/题干：I don't know ______ he will come tomorrow.。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 wh", "analysis": "【审题】题干：I don't know ______ he will come tomorrow. know 后为宾语从句，句意是“我不知道他明天是否来”，空格需表达“是否”。 【语法点/词汇】宾语从句连接词：that（陈述，无义）、whether/if（是否）、what/which 等（疑问意义）。whether 与 if 表“是否”；陈述句用 that；疑问词保留疑问义。否定主句 I don't know 后常见 whether 引导不确定内容。 【步骤】① 判断从句类型：know 后宾语从句。② 从句 he will come tomorrow 是完整陈述（不缺成分），但语义是“来不来”= 是否。③ 需“是否”→ whether。④ A. that——引导肯定事实，不表“是否”，与 don't know 的不确定矛盾，错。⑤ B. what——从句不缺宾语/表语，what 无处安放，错。⑥ C. whether ✓。⑤ D. which——表“哪一个”，句中无选择范围，错。 【答案】C. whether。 【易错】看到完整句就选 that；或把 whether 与 which 混淆；否定句后不知道要用“是否”。 【口诀/模板句】know 后接宾从，陈述 that“是否”whether；成分完整语义悬，whether/if 填中间。", "steps": ["【秒懂考点】宾语从句：whether表示是否", "【第一步：题干】我不知道他明天是否会来", "【第二步】\"是否\"用whether或if", "【第三步】that无意义，what什么，which哪个", "【答案】选whether"]});
  window.STUDY_DATA.questions.push({"id": "e11", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "____ he is young, he knows a lot about networks.", "options": ["Because", "Although", "So", "Unless"], "answer": "Although", "pitfalls": ["转折"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】Although 【考点】从句 【一步步怎么算】 ① 句子/题干：______ he is young, he knows a lot about networks.。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④", "analysis": "【审题】题干：______ he is young, he knows a lot about networks. 前半句“他年轻”，后半句“他懂很多网络知识”，语义转折。 【语法点/词汇】让步状语从句：Although/Though（虽然），不能与 but 连用。Because 因为（因果）；So 所以（结果）；Unless 除非（条件）。转折让步用 Although。 【步骤】① 读两句关系：年轻 ↔ 懂很多，相反/让步。② 让步连接词 Although/Though。③ A. Because——“因为年轻所以懂很多”，因果反了，错。④ B. Although ✓。⑤ C. So——“所以”放句首表结果，逻辑不通，错。⑥ D. Unless——“除非他年轻”，语义荒谬，错。⑦ 验证：Although he is young, he knows a lot. 虽年轻却博学。 【答案】B. Although。 【易错】选 Because 把转折当因果；或写 Although…but（双重连词错误）；或用 Unless 误判为条件。 【口诀/模板句】前弱后强是让步，Although/Though 打头住；有了 Although 不用 but，因为 Because 才对路。", "steps": ["【秒懂考点】让步状语从句：although虽然", "【第一步：题干】虽然他年轻，但他对网络了解很多", "【第二步】young和knows a lot是转折，用although", "【第三步】because因为、so所以、unless除非", "【答案】选Although"]});
  window.STUDY_DATA.questions.push({"id": "e13", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "Could you tell me ____?", "options": ["where does he live", "where he lives", "where he does live", "he lives where"], "answer": "where he lives", "pitfalls": ["陈述语序"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】where he lives 【考点】从句 【一步步怎么算】 ① 句子/题干：Could you tell me ______?。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 where he liv", "analysis": "【审题】题干：Could you tell me ______? tell me 后为宾语从句，选项涉及语序。间接疑问句要用陈述语序（主语在前，谓语在后）。 【语法点/词汇】宾语从句三要素：连接词 + 陈述语序 + 时态呼应。where does he live 是疑问语序（助动词 does 提前），错误；where he lives 是陈述语序，正确。 【步骤】① 主句 Could you tell me 是请求，后接宾语从句。② 从句要用陈述语序：where + 主语 + 谓语。③ A. where does he live——疑问语序（does 提前），错。④ B. where he lives ✓（he 主语在前，lives 谓语在后）。⑤ C. where he does live——do/does 强调语不用在此处且语序别扭，错。⑥ D. he lives where——where 位置错，疑问词必须在从句句首，错。 【答案】B. where he lives。 【易错】直接把疑问句语序搬进宾语从句；看到 tell me 就写成问句；忽略 where 要置前。 【口诀/模板句】宾从语序要陈述，疑问词后主谓顺；tell me where he lives，别把 does 往前拎。", "steps": ["【秒懂考点】宾语从句用陈述语序", "【第一步：题干】你能告诉我他住在哪里吗？", "【第二步】宾语从句必须用陈述语序：where he lives", "【第三步】where does he live是疑问语序，错误", "【答案】选where he lives"]});
  window.STUDY_DATA.questions.push({"id": "e18", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "The software must be ____ regularly to keep it safe.", "options": ["updated", "updated to", "up to date", "update"], "answer": "updated", "pitfalls": ["must be done"], "difficulty": 1, "source": "mock", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】updated 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The software must be ______ regularly to keep it s。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/", "analysis": "【审题】题干：The software must be ______ regularly to keep it safe. 有 must be（情态动词被动），空格需要过去分词作谓语的一部分。 【语法点/词汇】情态动词被动：must be + 过去分词。update 更新（及物），be updated 被更新。regularly 频率副词修饰动词。to keep it safe 是目的状语。 【步骤】① 看谓语框架：must be ______，缺的是 done（过去分词）。② update → updated。③ A. updated ✓（must be updated 被更新）。④ B. updated to——to 后缺宾语，结构多余，错。⑤ C. up to date 是形容词短语“最新的”，不能直接跟在 be 后表被动动作，且缺动词义，错。⑥ D. update——原形，must be 后不能接原形（那会变成 must do），错。 【答案】A. updated。 【易错】选 up to date（意思沾边但词性/结构不对）；或写 must be update 忘了变分词；或加 updated to 把及物用成不及物。 【口诀/模板句】must be + 过去分，被动结构记在心；be updated 才是“被更新”，up to date 是形容。", "steps": ["【秒懂考点】被动语态：软件被更新", "【第一步：题干】软件必须定期更新以保持安全", "【第二步】software和update是被动，must be updated", "【第三步】up to date是形容词\"最新的\"，不能直接用", "【答案】选updated"]});
  window.STUDY_DATA.questions.push({"id": "e19", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "stem": "阅读理解中，题干问 “What is the passage mainly about?” 时应优先看（ ）", "options": ["第一段最后一句与各段首句", "文章中出现次数最少的词", "最后一段所有细节", "作者心情描写"], "answer": "第一段最后一句与各段首句", "pitfalls": ["阅读技巧"], "difficulty": 1, "source": "highfreq", "typeLabel": "策略", "video": "v-english", "difficultyLabel": "基础", "tags": ["阅读策略", "ch-en-5"], "explainLevel": "subject-specific", "hint": "【结论】第一段最后一句与各段首句 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：阅读理解中，题干问 “What is the passage mainly about?” 时应优先。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/", "analysis": "【审题】题干问：阅读理解中 “What is the passage mainly about?” 应优先看什么。这是主旨题（main idea）策略题，不考语言点，考方法。 【语法点/词汇】主旨题技巧：读首段（尤其末句）+ 各段首句（topic sentences）+ 末段总结句，拼出全文中心。细节、生词、情绪都不是主旨来源。 【步骤】① 识别题型：mainly about = 主旨题。② 主旨位置：开篇引出、各段首句展开、结尾总结。③ A. 第一段最后一句与各段首句 ✓，覆盖中心线索。④ B. 出现次数最少的词——无关，错。⑤ C. 最后一段所有细节——细节不是主旨，错。⑥ D. 作者心情描写——态度题才看，且不是“主要关于”，错。⑦ 方法：先串首尾句，再概括，最后对选项找“能覆盖全文”的那项。 【答案】A. 第一段最后一句与各段首句。 【易错】把“最后一段”当万能主旨；或见关键词多就选；主旨必须概括全文而非某段细节。 【口诀/模板句】主旨看首尾与段首，细节例证不能留；题目问 mainly about，全文中心一句话。", "steps": ["【秒懂考点】主旨题：看首段末句和各段首句", "【第一步】mainly about问主旨", "【第二步】主题句通常在首段末句或各段首句", "【答案】第一段最后一句与各段首句"]});
  window.STUDY_DATA.questions.push({"id": "e24", "module": "public", "subject": "英语", "chapter": "ch-en-4", "knowledgePoint": "非谓语动词", "type": "single", "stem": "It took him two hours ____ the report.", "options": ["finish", "to finish", "finishing", "finished"], "answer": "to finish", "pitfalls": ["不定式"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["非谓语动词", "ch-en-4"], "explainLevel": "subject-specific", "hint": "【结论】to finish 【考点】非谓语动词 【一步步怎么算】 ① 句子/题干：It took him two hours ______ the report.。 ② 定位考点：非谓语动词。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确", "analysis": "【审题】题干：It took him two hours ______ the report. 句型 It takes/took sb. + 时间 + to do sth.，空格应为不定式作真正主语。 【语法点/词汇】It takes sb. some time to do sth.（花费某人多少时间做某事）。It 是形式主语，to do 是真正主语。finish 完成，report 报告。 【步骤】① 认句型：It took him two hours to do…（过去式 took）。② 固定结构：to + 动词原形。③ A. finish——缺 to，语法不成立，错。④ B. to finish ✓。⑤ C. finishing——动名词不能用于 It took…to do 句型，错。⑥ D. finished——过去分词不能作真正主语，错。⑦ 回译：他花了两个小时完成这份报告。 【答案】B. to finish。 【易错】与 It is no use doing / spend time doing 混淆；或看到 took 就用 doing；忘记 to 后用原形（finish 而非 finishes）。 【口诀/模板句】It takes sb. time to do，形式主语 to 置后；spend 用 doing，take 用 to do，句型一换词形变。", "steps": ["【秒懂考点】It takes sb time to do，固定", "【第一步】took him two hours to finish，不定式", "【答案】选to finish"]});
  window.STUDY_DATA.questions.push({"id": "e25", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "He is responsible ____ the network maintenance.", "options": ["to", "for", "with", "about"], "answer": "for", "pitfalls": ["for固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】for 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He is responsible ______ the network maintenance.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④", "analysis": "【审题】题干：He is responsible ______ the network maintenance. 考形容词 responsible 的介词搭配。 【语法点/词汇】be responsible for sth.（对……负责）；be responsible to sb.（向某人负责）。题干后是物（network maintenan网络维护），用 for。with/about 不与 responsible 构成此义。 【步骤】① 形容词短语：responsible + 介词。② 负责某事 = responsible for。③ A. to——responsible to 是“向（上级）负责”，后接人，此处是事，错。④ B. for ✓。⑤ C. with——无此搭配，错。⑥ D. about——无此搭配，错。 【答案】B. for。 【易错】把 responsible to（向谁负责）和 responsible for（对什么事负责）混用；或按中文“对”想当然选 to。 【口诀/模板句】负责事情用 for，对人负责用 to；be responsible for the work，be responsible to the boss。", "steps": ["【秒懂考点】be responsible for，对……负责", "【第一步】for负责网络维护", "【答案】选for"]});
  window.STUDY_DATA.questions.push({"id": "e26", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "The two plans are quite ____ from each other.", "options": ["same", "different", "similar", "like"], "answer": "different", "pitfalls": ["from搭配"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】different 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The two plans are quite ______ from each other.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭", "analysis": "【审题】题干：The two plans are quite ______ from each other. 有 from each other，需与 from 搭配的形容词。 【语法点/词汇】be different from（与……不同）；be the same as（与……相同）；be similar to（与……相似）。like 作介词“像”，不与 from each other 搭。 【步骤】① 信号词 from each other → different from。② A. same——要说 the same as，且 the two plans 不同还是相同取决于搭配；same 不与 from 连用，错。③ B. different ✓（quite different from each other 彼此很不同）。④ C. similar——应配 to，不是 from，错。⑤ D. like——不能 be like from each other，结构冲突，错。 【答案】B. different。 【易错】similar from、same from 是典型错误搭配；记住 from 只跟 different 系。 【口诀/模板句】different from 记心间，same as similar to 不要换；见到 from each other，", "steps": ["【秒懂考点】be different from，与……不同", "【第一步】两计划彼此不同", "【第二步】same相同，similar相似，like像", "【答案】选different"]});
  window.STUDY_DATA.questions.push({"id": "e27", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "He is interested ____ computer networks.", "options": ["at", "in", "on", "for"], "answer": "in", "pitfalls": ["in固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】in 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He is interested ______ computer networks.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 i", "analysis": "【审题】题干：He is interested ______ computer networks. 考 be interested 的介词。 【语法点/词汇】be interested in sth./doing sth.（对……感兴趣）。interest 的形容词 interested 固定配 in。at/on/for 均不搭配。 【步骤】① 固定短语：be interested in。② 代入：interested in computer networks（对计算机网络感兴趣）。③ A. at——无，错。④ B. in ✓。⑤ C. on——无，错。⑥ D. for——无，错。⑦ 注意 interested 后可接 in doing，不可接 to do 表兴趣（to do 多表“有兴趣去做”）。 【答案】B. in。 【易错】与 be good at / be keen on 混淆；或写 be interested on/for；把 interesting（令人感兴趣的）主语物、interested 主语人搞反。 【口诀/模板句】人 interested 用 in，物 interesting 才是“趣”；be interested in doing，介词就是 in 别移。", "steps": ["【秒懂考点】be interested in，对……感兴趣", "【第一步】in表示在某方面", "【答案】选in"]});
  window.STUDY_DATA.questions.push({"id": "e28", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "Please pay attention ____ the spelling.", "options": ["to", "for", "on", "in"], "answer": "to", "pitfalls": ["to固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】to 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Please pay attention ______ the spelling.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 to", "analysis": "【审题】题干：Please pay attention ______ the spelling. 考 pay attention 的介词搭配。 【语法点/词汇】pay attention to sth./doing sth.（注意……）。to 在此为介词，后接名词/动名词。spelling 拼写。 【步骤】① 固定搭配：pay attention to。② 代入：pay attention to the spelling（注意拼写）。③ A. to ✓。④ B. for——无此搭配，错。⑤ C. on——无，错。⑥ D. in——无，错。⑦ 拓展：pay no attention to、draw attention to。 【答案】A. to。 【易错】把 to 当不定式想接原形；或写 pay attention on（受中文“在拼写上注意”影响）。 【口诀/模板句】pay attention to，to 是介词别小瞧；注意某事 to sth.，接 doing 也合法。", "steps": ["【秒懂考点】pay attention to，注意，to是介词", "【第一步】注意拼写", "【答案】选to"]});
  window.STUDY_DATA.questions.push({"id": "e29", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "We should depend ____ ourselves.", "options": ["on", "in", "to", "of"], "answer": "on", "pitfalls": ["on固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】on 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：We should depend ______ ourselves.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 on。 【其他选项", "analysis": "【审题】题干：We should depend ______ ourselves. 考 depend 的介词。 【语法点/词汇】depend on/upon sb./sth.（依靠、依赖、取决于）。on 与 upon 可互换，选项用 on。depend 通常不与 in/to/of 连用表此义。 【步骤】① 固定短语：depend on。② 代入：depend on ourselves（依靠我们自己）。③ A. on ✓。④ B. in——错。⑤ C. to——错。⑥ D. of——错。⑦ 拓展：It depends.（视情况而定）；depend on it that…。 【答案】A. on。 【易错】与 rely on 混用介词；或按中文“依赖于”选 to/of。 【口诀/模板句】depend on / upon 记牢，依靠取决于它包；rely on 同义也 on，of in to 都不要。", "steps": ["【秒懂考点】depend on，依靠", "【第一步】我们应该依靠自己", "【答案】选on"]});
  window.STUDY_DATA.questions.push({"id": "e30", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "The word “reliable” means ____.", "options": ["可以依赖的", "昂贵的", "临时的", "复杂的"], "answer": "可以依赖的", "pitfalls": ["构词法"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】可以依赖的 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The word “reliable” means ______.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 可以依赖的。 ", "analysis": "【审题】题干：The word “reliable” means ______. 词义题，问 reliable 的意思。 【语法点/词汇】reliable = able to be relied on，可依赖的、可靠的。构词：rely（依靠）+ -able（能……的）。词根记忆：re- + ly→rely + able。 【步骤】① 拆词：rely（依赖）+ -able（可……的）。② reliable = 可以依赖的、可靠的。③ A. 可以依赖的 ✓。④ B. 昂贵的（expensive）——无关，错。⑤ C. 临时的（temporary）——无关，错。⑥ D. 复杂的（complex）——无关，错。 【答案】A. 可以依赖的。 【易错】把 reliable 和 related/relation 混淆；或凭字面“re-”猜“反复”而错译。 【口诀/模板句】-able 是“可、能”，rely 依赖 reliable 稳；词根词缀一拼，词义自然分。", "steps": ["【秒懂考点】reliable = 可靠的，可以依赖的", "【第一步】rely动词依赖，-able形容词后缀，可……的", "【答案】选可以依赖的"]});
  window.STUDY_DATA.questions.push({"id": "e33", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "She is proud ____ her daughter.", "options": ["for", "of", "in", "on"], "answer": "of", "pitfalls": ["of固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】of 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：She is proud ______ her daughter.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 of。 【其他选项为", "analysis": "【审题】题干：She is proud ______ her daughter. 考 proud 的介词搭配。 【语法点/词汇】be proud of（为……自豪）。proud 是形容词，固定 of。pride 是名词，take pride in。 【步骤】① 固定搭配：be proud of。② 代入：proud of her daughter（为女儿自豪）。③ A. for——错。④ B. of ✓。⑤ C. in——错（take pride in 才用 in）。⑥ D. on——错。 【答案】B. of。 【易错】把 be proud of 与 take pride in 的介词互换；或受“为”影响选 for。 【口诀/模板句】be proud of 记周全，take pride in 换名又换介词；proud 形容 of，pride 名词 in 才是理。", "steps": ["【秒懂考点】be proud of，为……自豪", "【第一步】of为女儿骄傲", "【答案】选of"]});
  window.STUDY_DATA.questions.push({"id": "e35", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "Water ____ at 100°C.", "options": ["boils", "is boiled", "boiled", "has boiled"], "answer": "boils", "pitfalls": ["客观真理"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】boils 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：Water ______ at 100°C.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 boils。 【其他选项为何不对】 ", "analysis": "【审题】题干：Water ______ at 100°C. 表客观真理/科学事实，不受主句时态影响，用一般现在时。 【语法点/词汇】一般现在时表客观真理、科学事实、习惯。boil 沸腾，三单 boils。at 100°C 是温度条件。 【步骤】① 判断语义：水在100度沸腾是客观事实。② 客观真理 → 一般现在时。③ 主语 Water 不可数，视为三单 → boils。④ A. boils ✓。⑤ B. is boiled——被动“被煮沸”，句意变成“水被（谁）煮沸”，不是事实陈述，错。⑥ C. boiled——过去时，事实不只在过去，错。⑦ D. has boiled——完成时无持续/影响语境，错。 【答案】A. boils。 【易错】主句是过去时就跟着用过去（宾语从句中真理仍用现在时）；或误选被动。 【口诀/模板句】真理事实用现在，三单加 s 别乱来；Water boils at 100，时态跟着语义派。", "steps": ["【秒懂考点】客观真理用一般现在时，主动", "【第一步】水在100度沸腾，自然规律", "【第二步】boils，不用被动", "【答案】选boils"]});
  window.STUDY_DATA.questions.push({"id": "e36", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "This book ____ by Lu Xun.", "options": ["wrote", "was written", "is writing", "writes"], "answer": "was written", "pitfalls": ["被动"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】was written 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：This book ______ by Lu Xun.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 was wri", "analysis": "【审题】题干：This book ______ by Lu Xun. 有 by + 人（鲁迅），说明被动；书写成于过去，用一般过去时被动。 【语法点/词汇】一般过去时被动：was/were + 过去分词。write → written（不规则）。by Lu Xun 是施动者。book 是“被写”的对象。 【步骤】① by Lu Xun → 被动。② 写书是过去动作 → was written。③ A. wrote——主动“鲁迅写”，但主语是 book，错。④ B. was written ✓。⑤ C. is writing——现在进行主动，错。⑥ D. writes——主动一般现在，错。 【答案】B. was written。 【易错】写成 was wrote（write 过去分词是 written 不是 wrote）；或选 was writing。 【口诀/模板句】by 后是作者，主语是书用被动；was written 记不规则，write wrote written 别忘掉。", "steps": ["【秒懂考点】被动语态：书被鲁迅写", "【第一步】过去时被动，was written", "【第二步】wrote主动，is writing现在进行主动", "【答案】选was written"]});
  window.STUDY_DATA.questions.push({"id": "e37", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "Look! The children ____ football.", "options": ["play", "played", "are playing", "have played"], "answer": "are playing", "pitfalls": ["look标志"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】are playing 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：Look! The children ______ football.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是", "analysis": "【审题】题干：Look! The children ______ football. Look! 是现在进行时的标志词，表示说话时正在发生。 【语法点/词汇】现在进行时：am/is/are + doing。Look!/Listen!/now/at the moment 是标志。children 是复数，用 are playing。 【步骤】① 标志词 Look! → 现在进行时。② 主语 children 复数 → are + playing。③ A. play——一般现在表习惯，与 Look! 冲突，错。④ B. played——过去，错。⑤ C. are playing ✓。⑥ D. have played——完成时强调结果/持续，不强调“此刻正在踢”，错。 【答案】C. are playing。 【易错】children 不规则复数误当三单用 is playing；或忽略 Look! 用一般现在。 【口诀/模板句】Look Listen 要用 be doing，说话当下正进行；children 复数用 are，playing 现在分词别忘 ing。", "steps": ["【秒懂考点】Look! 现在进行时", "【第一步】孩子们正在踢足球，are playing", "【答案】选are playing"]});
  window.STUDY_DATA.questions.push({"id": "e41", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "I know the man ____ is standing there.", "options": ["who", "which", "where", "what"], "answer": "who", "pitfalls": ["人who"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】who 【考点】从句 【一步步怎么算】 ① 句子/题干：I know the man ______ is standing there.。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 who。 【其他", "analysis": "【审题】题干：I know the man ______ is standing there. 定语从句，先行词 the man（人），从句 is standing there 缺主语。 【语法点/词汇】关系代词 who/that 指人并作主语；which 指物；where 作地点状语；what 不引导定语从句。 【步骤】① 先行词 the man（人）。② 从句 ______ is standing there——缺主语。③ 人 + 主语 → who（或 that）。④ A. who ✓。⑤ B. which——指物，错。⑥ C. where——地点状语，错。⑦ D. what——不能引导定语从句，错。 【答案】A. who。 【易错】人、物关系词混用；或用 whom（宾格，不能作主语）；what 误入定语从句。 【口诀/模板句】人主 who 人宾 whom，物主物宾 which；where 只管地点状，what 不把定从帮。", "steps": ["【秒懂考点】定语从句：who指人，作主语", "【第一步】man是人，在从句中作主语", "【第二步】which指物，where地点，what不引导", "【答案】选who"]});
  window.STUDY_DATA.questions.push({"id": "e42", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "This is the school ____ I studied.", "options": ["which", "where", "that", "what"], "answer": "where", "pitfalls": ["where地点"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】where 【考点】从句 【一步步怎么算】 ① 句子/题干：This is the school ______ I studied.。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 where。 【其他", "analysis": "【审题】题干：This is the school ______ I studied. 先行词 the school（地点），从句 I studied 主谓完整（study 可不及物），缺地点状语。 【语法点/词汇】关系副词 where = in/at which，引导定语从句作地点状语。若从句缺主宾则用 which/that；本句 studied 不缺宾语，缺“在哪里学习”。 【步骤】① 先行词 school（地点）。② 从句 I studied——主谓已全，缺地点状语。③ 地点状语 → where。④ A. which——若用 which 应为 at/in which 且作宾语时才直接 which，此处缺状语，直接 which 不妥，错。⑤ B. where ✓。⑥ C. that——代主宾，不作状语，错。⑦ D. what——不引导定语从句，错。 【答案】B. where。 【易错】见 school 是“地方”却用 which/that；或以为 studied 必须有宾语而强填 which。区分：I studied (in) the school → where；I visited the school → which/that。 【口诀/模板句】从句完整缺状语，地点 where 时间 when；缺宾 which/that 来补，成分分析是正路。", "steps": ["【秒懂考点】where引导定语从句，在从句中作地点状语", "【第一步】study in the school，需要介词in，where=in which", "【第二步】which作主语宾语，这里不缺主语", "【答案】选where"]});
  window.STUDY_DATA.questions.push({"id": "e43", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "He asked me ____ I had finished it.", "options": ["that", "what", "if", "which"], "answer": "if", "pitfalls": ["是否"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】if 【考点】从句 【一步步怎么算】 ① 句子/题干：He asked me ______ I had finished it.。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 if。 【其他选项为何不", "analysis": "【审题】题干：He asked me ______ I had finished it. asked 后宾语从句，句意“他问我是否完成了它”。 【语法点/词汇】ask 后常接 if/whether 引导“是否”；that 引导陈述内容；what/which 需有疑问意义。 【步骤】① 主句 He asked me，后接从句。② 从句 I had finished it 成分完整，但语义是“完成了没有”。③ “是否”→ if/whether。④ A. that——只陈述事实，不表“是否”，错。⑤ B. what——从句不缺宾语（it 已是宾语），错。⑥ C. if ✓。⑦ D. which——无选择项，错。 【答案】C. if。 【易错】ask that（错，ask 一般不直接接 that 表“问是否”）；或选 which。注意：if 作“是否”时不可放句首，whether 则可以。 【口诀/模板句】ask 后表“是否”用 if，宾从完整语义悬；that 陈述 what 疑，是否二字 if 填。", "steps": ["【秒懂考点】宾语从句：if表示是否", "【第一步】他问我是否完成了，if=whether", "【第二步】that无意义，what什么，which哪个", "【答案】选if"]});
  window.STUDY_DATA.questions.push({"id": "e44", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "____ he comes, I will tell him.", "options": ["If", "Unless", "Though", "Because"], "answer": "If", "pitfalls": ["条件"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】If 【考点】从句 【一步步怎么算】 ① 句子/题干：______ he comes, I will tell him.。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 If。 【其他选项为何不对】 •", "analysis": "【审题】题干：______ he comes, I will tell him. 前句条件，后句结果（主将从现）。 【语法点/词汇】条件状语从句：If（如果）引导，主句将来时，从句一般现在时。Unless = if not（除非）；Though 虽然；Because 因为。 【步骤】① 后句 I will tell him 是将来结果。② 前句应是条件“如果他来”。③ A. If ✓。④ B. Unless——“除非他来，否则我告诉他”，逻辑不通（应是“否则不告诉”），错。⑤ C. Though——让步“虽然他来”，与 will tell 逻辑不搭，错。⑥ D. Because——“因为他来所以我告诉他”，因果牵强且主将从现不对，错。 【答案】A. If。 【易错】Unless 与 if 混；或从句写成 will come（主将从现违背）。 【口诀/模板句】主将从现记分明：if 引导从句用一般；Unless 等于 if not，逻辑方向要看清。", "steps": ["【秒懂考点】条件状语从句：if如果", "【第一步】如果他来，我会告诉他", "【第二步】unless除非，though虽然，because因为", "【答案】选If"]});
  window.STUDY_DATA.questions.push({"id": "e48", "module": "public", "subject": "英语", "chapter": "ch-en-4", "knowledgePoint": "非谓语动词", "type": "single", "stem": "I enjoy ____ English.", "options": ["read", "to read", "reading", "readed"], "answer": "reading", "pitfalls": ["enjoy doing"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["非谓语动词", "ch-en-4"], "explainLevel": "subject-specific", "hint": "【结论】reading 【考点】非谓语动词 【一步步怎么算】 ① 句子/题干：I enjoy ______ English.。 ② 定位考点：非谓语动词。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 reading。 【其他选项为", "analysis": "【审题】题干：I enjoy ______ English. 考 enjoy 后的非谓语形式。 【语法点/词汇】enjoy + doing（动名词）。只接 doing 的动词：enjoy, finish, mind, practice, suggest, avoid, give up, look forward to 等。 【步骤】① enjoy 后必须 doing。② reading ✓。③ A. read——原形，错。④ B. to read——不定式，enjoy 不接 to do，错。⑤ C. reading ✓。⑥ D. readed——形式错误（过去分词是 read），错。 【答案】C. reading。 【易错】与 want/decide to do 混；或写 enjoy to read。 【口诀/模板句】enjoy finish mind practice，只跟 doing 不跟 to；背下这批动词表，非谓语题不摔倒。", "steps": ["【秒懂考点】enjoy doing，动名词", "【第一步】enjoy后面加动名词，enjoy reading", "【第二步】不能加不定式", "【答案】选reading"]});
  window.STUDY_DATA.questions.push({"id": "e49", "module": "public", "subject": "英语", "chapter": "ch-en-4", "knowledgePoint": "非谓语动词", "type": "single", "stem": "It is important ____ hard.", "options": ["study", "to study", "studying", "studied"], "answer": "to study", "pitfalls": ["不定式主语"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["非谓语动词", "ch-en-4"], "explainLevel": "subject-specific", "hint": "【结论】to study 【考点】非谓语动词 【一步步怎么算】 ① 句子/题干：It is important ______ hard.。 ② 定位考点：非谓语动词。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 to study。", "analysis": "【审题】题干：It is important ______ hard. It 作形式主语，真正主语在后，用不定式。 【语法点/词汇】It is + adj. + to do sth.（做某事是……的）。常见：It is important/necessary/difficult to do。也可 It is no use doing。 【步骤】① 句型 It is important to do。② to study hard（努力学习很重要）。③ A. study——缺 to，错。④ B. to study ✓。⑤ C. studying——本句型标准形式是 to do；若用 doing 需变为 Studying hard is important，语法不同，本空在 It is important 后应用 to do，错。⑥ D. studied——错。 【答案】B. to study。 【易错】与 It is no use/good doing 混；或形式主语后填动名词。 【口诀/模板句】It is adj. to do 好，形式主语 to 置后；no use 才用 doing，两条句型分开记。", "steps": ["【秒懂考点】It is important to do，不定式", "【第一步】it是形式主语，真正主语是to study hard", "【答案】选to study"]});
  window.STUDY_DATA.questions.push({"id": "e50", "module": "public", "subject": "英语", "chapter": "ch-en-4", "knowledgePoint": "非谓语动词", "type": "single", "stem": "I have a lot of work ____.", "options": ["do", "to do", "doing", "done"], "answer": "to do", "pitfalls": ["不定式"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["非谓语动词", "ch-en-4"], "explainLevel": "subject-specific", "hint": "【结论】to do 【考点】非谓语动词 【一步步怎么算】 ① 句子/题干：I have a lot of work ______.。 ② 定位考点：非谓语动词。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 to do。 【其他选项", "analysis": "【审题】题干：I have a lot of work ______. have + 名词 + to do，不定式作 work 的后置定语（或 have sth. to do 句型）。 【语法点/词汇】have + 宾语 + to do（有……要做）。work 与 do 是动宾关系（do the work），主动形式表被动含义，用 to do。 【步骤】① I have a lot of work…结构：have sth. to do。② to do 修饰 work，意为“许多要做的工作”。③ A. do——缺 to，错。④ B. to do ✓。⑤ C. doing——I have work doing 不表示“有工作要做”，错。⑥ D. done——have work done 是“让别人做工作”，句意不通，错。 【答案】B. to do。 【易错】与 have sth. done（请人做/被做）混淆；或用 doing。 【口诀/模板句】have sth. to do 有事做，have sth. done 找人做；to do 主动被动义，done 才是过去分词搁。", "steps": ["【秒懂考点】不定式作定语：work to do", "【第一步】a lot of work to do，要做的工作", "【第二步】to do修饰work，将来要做", "【答案】选to do"]});
  window.STUDY_DATA.questions.push({"id": "e55", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "stem": "细节题最有效的定位方法是（ ）", "options": ["通读全文背诵", "找题干关键词回原文定位", "只看首段", "猜作者情绪"], "answer": "找题干关键词回原文定位", "pitfalls": ["阅读技巧"], "difficulty": 1, "source": "highfreq", "typeLabel": "策略", "video": "v-english", "difficultyLabel": "基础", "tags": ["阅读策略", "ch-en-5"], "explainLevel": "subject-specific", "hint": "【结论】找题干关键词回原文定位 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：细节题最有效的定位方法是（ ）。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 找题干关键词回原文定位。 【其他选项为何不", "analysis": "【审题】题干：细节题最有效的定位方法是（ ）。阅读策略题，考细节题（detail question）的解题步骤。 【语法点/词汇】细节题解法：圈题干关键词（人名、数字、专有名词、核心名词）→ 回原文定位 → 对照选项同义替换。不靠通读背诵或猜情绪。 【步骤】① 细节题特征：According to…, Which of the following is true 等。② 高效路径：关键词定位法。③ A. 通读全文背诵——费时且抓不住点，错。④ B. 找题干关键词回原文定位 ✓。⑤ C. 只看首段——细节可在任意段，错。⑥ D. 猜作者情绪——态度题技巧，错。 【答案】B. 找题干关键词回原文定位。 【易错】先看选项再乱找；或用主旨题方法做细节题；忽略同义替换导致定位后仍选错。 【口诀/模板句】细节题，关键词，回文定位看原句；同义替换是", "steps": ["【秒懂考点】细节题：关键词定位", "【第一步】题干关键词回原文找", "【答案】找题干关键词回原文定位"]});
  window.STUDY_DATA.questions.push({"id": "e56", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "stem": "词义猜测题优先看（ ）", "options": ["上下文与转折词", "字典", "题干", "选项长度"], "answer": "上下文与转折词", "pitfalls": ["上下文"], "difficulty": 1, "source": "highfreq", "typeLabel": "策略", "video": "v-english", "difficultyLabel": "基础", "tags": ["阅读策略", "ch-en-5"], "explainLevel": "subject-specific", "hint": "【结论】上下文与转折词 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：词义猜测题优先看（ ）。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 上下文与转折词。 【其他选项为何不对】 • B「字典」：语", "analysis": "【审题】题干：词义猜测题优先看（ ）。阅读策略题，考词义猜测（word meaning / guessing）的方法。 【语法点/词汇】词义猜测依据：上下文线索、转折词（but/however/yet）、同位语、举例、构词法。不能查字典（考试不允许），不能看选项长度或只看题干。 【步骤】① 识别题型：The word “…” probably means…。② 核心方法：读前后句，抓转折/并列/解释。③ A. 上下文与转折词 ✓，如 but 后是反义。④ B. 字典——考场不现实，错。⑤ C. 题干——只告诉你要猜哪个词，不给线索，错。⑥ D. 选项长度——与词义无关，错。⑦ 补充：若前句说 X is useful, however Y is useless，则 Y 与 useful 相反。 【答案】A. 上下文与转折词。 【易错】凭生词本身瞎猜；只看生词所在半句不读前后；忽略 however/but/in other words 等信号。 【口诀/模板句】词义猜测看上下文，转折同位是路标；in other words 同义找，but 前后常对抛。", "steps": ["【秒懂考点】词义猜测：看上下文", "【第一步】通过上下文和转折词but/however推断", "【答案】上下文与转折词"]});
  window.STUDY_DATA.questions.push({"id": "e58", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "stem": "主旨题标题应能覆盖（ ）", "options": ["首段", "全文中心", "末段细节", "举例"], "answer": "全文中心", "pitfalls": ["覆盖全文"], "difficulty": 1, "source": "highfreq", "typeLabel": "策略", "video": "v-english", "difficultyLabel": "基础", "tags": ["阅读策略", "ch-en-5"], "explainLevel": "subject-specific", "hint": "【结论】全文中心 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：主旨题标题应能覆盖（ ）。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 全文中心。 【其他选项为何不对】 • A「首段」：语法结构与时", "analysis": "【审题】题干：主旨题标题应能覆盖（ ）。考主旨题/标题选择的标准。 【语法点/词汇】好标题特征：概括全文中心（main idea），能覆盖各段主旨，不以偏概全。标题题（best title）比普通主旨更凝练。 【步骤】① 标题 ≠ 某段细节，必须全文覆盖。② A. 首段——只是一部分，错。③ B. 全文中心 ✓。④ C. 末段细节——以偏概全，错。⑤ D. 举例——例子服务主题，不能当标题，错。⑥ 验证：读各段首句归纳一句中心，再看哪个选项最能统摄。 【答案】B. 全文中心。 【易错】标题过宽（全是什么都包）或过窄（只说某段）；被细节强的选项吸引。 【口诀/模板句】标题要盖全文面，不大不小正中间；段落细节不能占，中心一句最关键。", "steps": ["【秒懂考点】主旨标题覆盖全文", "【第一步】不能只覆盖某一段或细节", "【答案】全文中心"]});
  window.STUDY_DATA.questions.push({"id": "e65", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "I look forward to ____ from you soon.", "options": ["hear", "hearing", "be hearing", "have heard"], "answer": "hearing", "pitfalls": ["to介词"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】hearing 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：I look forward to ______ from you soon.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是", "analysis": "【审题】题干：I look forward to ______ from you soon. look forward to 中的 to 是介词，后接动名词。 【语法点/词汇】look forward to + doing（盼望做）。to 为介词，类似：be used to doing, pay attention to doing, object to doing, devote…to doing。 【步骤】① 短语 look forward to，to 是介词。② 介词后用 doing → hearing from（收到……来信）。③ A. hear——原形，错。④ B. hearing ✓。⑤ C. be hearing——进行式多余，错。⑥ D. have heard——完成式不合搭配，错。⑦ 翻译：我盼望不久收到你的来信。 【答案】B. hearing。 【易错】把 to 当不定式想接 hear；与 expect/want to do 混淆。 【口诀/模板句】look forward to doing，to 是介词要清醒；attention, used to, devote to，后头一律动名词。", "steps": ["【秒懂考点】look forward to doing，期待", "【第一步】hearing，动名词", "【答案】选hearing"]});
  window.STUDY_DATA.questions.push({"id": "e66", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "He is not good ____ math.", "options": ["at", "in", "for", "on"], "answer": "at", "pitfalls": ["at固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】at 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He is not good ______ math.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 at。 【其他选项为何不对】 •", "analysis": "【审题】题干：He is not good ______ math. 考 be good 的介词搭配。 【语法点/词汇】be good at sth./doing（擅长）；be good for（对……有益）；be good to（对……好）。本题是“不擅长数学”，用 at。 【步骤】① 语义“擅长/不擅长数学”→ be good at。② 否定 not good at 仍用 at。③ A. at ✓。④ B. in——无此搭配表擅长，错。⑤ C. for——be good for 是“对……有益”（如 Milk is good for health），错。⑥ D. on——无，错。 【答案】A. at。 【易错】good at / good for / good to 三者混；not 后换介词（不换）。 【口诀/模板句】good at 擅长事，good for 有好处，good to 对人好；否定 not 介词不变，at math 记牢靠。", "steps": ["【秒懂考点】be good at，擅长", "【第一步】at数学不擅长", "【答案】选at"]});
  window.STUDY_DATA.questions.push({"id": "e70", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "I ____ TV at eight last night.", "options": ["watch", "watched", "am watching", "was watching"], "answer": "was watching", "pitfalls": ["具体时间点"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】was watching 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：I ______ TV at eight last night.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 w", "analysis": "【审题】题干：I ______ TV at eight last night. at eight last night 是过去具体时间点，表示当时正在进行的动作。 【语法点/词汇】过去进行时：was/were + doing，表过去某时刻正在做。与一般过去时（一次性完成）区分。 【步骤】① 时间 at eight last night（昨晚八点）→ 过去某点。② 当时正在看电视 → was watching。③ A. watch——现在，错。④ B. watched——过去一般，只表“看过”，不强调八点那会儿正在看，欠佳。⑤ C. am watching——现在进行，错。⑥ D. was watching ✓。 【答案】D. was watching。 【易错】last night 就用一般过去；I 是单数却写 were watching。 【口诀/模板句】过去某点正在做，was/were + doing；last night at eight，八点那阵正看着。", "steps": ["【秒懂考点】at eight last night，过去进行时", "【第一步】昨晚8点正在看电视，was watching", "【答案】选was watching"]});
  window.STUDY_DATA.questions.push({"id": "e72", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "If it ____ tomorrow, we will stay at home.", "options": ["rains", "will rain", "rained", "raining"], "answer": "rains", "pitfalls": ["主将从现"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】rains 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：If it ______ tomorrow, we will stay at home.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确", "analysis": "【审题】题干：If it ______ tomorrow, we will stay at home. 条件状语从句，主句 will，从句用一般现在（主将从现）。 【语法点/词汇】If 引导条件从句：主句将来时，从句一般现在时表将来。rain 下雨，it 是形式主语，动词用 rains。 【步骤】① 主句 we will stay 是将来。② if 从句用一般现在表将来。③ 主语 it 三单 → rains。④ A. rains ✓。⑤ B. will rain——主将从现违背，错。⑥ C. rained——过去，错。⑦ D. raining——非谓语不能作谓语，错。 【答案】A. rains。 【易错】从句写 will rain；it rains 的三单 -s 漏掉。 【口诀/模板句】主将从现 if 从，will 不进 if 中；it rains 三单加 s，明天的事现在说。", "steps": ["【秒懂考点】主将从现：if从句一般现在时", "【第一步】明天下雨用rains，不能用will rain", "【答案】选rains"]});
  window.STUDY_DATA.questions.push({"id": "e73", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "stem": "The room ____ tomorrow.", "options": ["cleans", "is cleaned", "will be cleaned", "will clean"], "answer": "will be cleaned", "pitfalls": ["被动"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["时态与语态", "ch-en-2"], "explainLevel": "subject-specific", "hint": "【结论】will be cleaned 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：The room ______ tomorrow.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 will ", "analysis": "【审题】题干：The room ______ tomorrow. tomorrow 表将来；房间是“被打扫”，用将来时被动。 【语法点/词汇】一般将来时被动：will be + 过去分词。clean 打扫，room 是宾语提前做主语。 【步骤】① tomorrow → will。② room 与 clean 是动宾关系 → 被动 be cleaned。③ 合成 will be cleaned。④ A. cleans——主动一般现在，错。⑤ B. is cleaned——现在被动，与 tomorrow 不符，错。⑥ C. will be cleaned ✓。⑦ D. will clean——主动，房间不能自己打扫自己，错。 【答案】C. will be cleaned。 【易错】只选 will clean 忽略被动；或 is cleaned 忘了将来。 【口诀/模板句】tomorrow 将来 will，主语是物想被动；will be cleaned 打扫好，主动被动要分清。", "steps": ["【秒懂考点】将来时被动：房间被打扫", "【第一步】will be cleaned，明天将被打扫", "【第二步】will clean主动，is cleaned现在被动", "【答案】选will be cleaned"]});
  window.STUDY_DATA.questions.push({"id": "e79", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "从句", "type": "single", "stem": "Do you know ____?", "options": ["where does he live", "where he lives", "where he does live", "he lives where"], "answer": "where he lives", "pitfalls": ["陈述语序"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["从句", "ch-en-3"], "explainLevel": "subject-specific", "hint": "【结论】where he lives 【考点】从句 【一步步怎么算】 ① 句子/题干：Do you know ______?。 ② 定位考点：从句。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 where he lives。 【其", "analysis": "【审题】题干：Do you know ______? know 后宾语从句，考语序。 【语法点/词汇】宾语从句用陈述语序：疑问词 + 主语 + 谓语。where does he live 是疑问语序，错误。 【步骤】① Do you know + 宾语从句。② 从句要说“他住在哪里”→ where he lives。③ A. where does he live——疑问语序，错。④ B. where he lives ✓。⑤ C. where he does live——强调结构多余且不自然，错。⑥ D. he lives where——where 必须在从句句首，错。⑦ lives 的 -s 因 he 三单，不可漏。 【答案】B. where he lives。 【易错】口语语序带进书面；do/does 在宾从里乱加；三单 lives 写成 live。 【口诀/模板句】宾从语序陈述化，疑问词后主语加；where he lives 要加 s，do does 往出拿。", "steps": ["【秒懂考点】宾语从句陈述语序", "【第一步】where he lives，陈述语序", "【答案】选where he lives"]});
  window.STUDY_DATA.questions.push({"id": "e80", "module": "public", "subject": "英语", "chapter": "ch-en-4", "knowledgePoint": "非谓语动词", "type": "single", "stem": "The teacher told us ____ more books.", "options": ["read", "to read", "reading", "readed"], "answer": "to read", "pitfalls": ["tell to do"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["非谓语动词", "ch-en-4"], "explainLevel": "subject-specific", "hint": "【结论】to read 【考点】非谓语动词 【一步步怎么算】 ① 句子/题干：The teacher told us ______ more books.。 ② 定位考点：非谓语动词。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 ", "analysis": "【审题】题干：The teacher told us ______ more books. 考 tell sb. to do sth. 句型。 【语法点/词汇】tell/ask/order/want/advise sb. to do（不定式作宾补）。否定：tell sb. not to do。 【步骤】① 句型 tell us to do。② to read more books（多读书）。③ A. read——缺 to，错。④ B. to read ✓。⑤ C. reading——tell 不接 sb. doing 表命令，错。⑥ D. readed——形式错，错。 【答案】B. to read。 【易错】与 make/let/have sb. do（不带 to）混淆；或写 told us reading。 【口诀/模板句】tell ask want 加 to do，make let have 要裸奔；感官动词也裸，被动还原 to 别昏。", "steps": ["【秒懂考点】tell sb to do，不定式作宾补", "【第一步】told us to read more books", "【第二步】tell后面接不定式，不能接动名词", "【答案】选to read"]});
  window.STUDY_DATA.questions.push({"id": "e85", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "stem": "阅读时遇生词应（ ）", "options": ["立刻查字典打断", "先猜测再继续", "跳过全文", "只记中文"], "answer": "先猜测再继续", "pitfalls": ["阅读技巧"], "difficulty": 1, "source": "highfreq", "typeLabel": "策略", "video": "v-english", "difficultyLabel": "基础", "tags": ["阅读策略", "ch-en-5"], "explainLevel": "subject-specific", "hint": "【结论】先猜测再继续 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：阅读时遇生词应（ ）。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 先猜测再继续。 【其他选项为何不对】 • A「立刻查字典打断」", "analysis": "【审题】题干：阅读时遇生词应（ ）。考考场阅读生词处理策略。 【语法点/词汇】正确策略：先根据上下文猜测，继续读下去；不立刻查字典（打断思路且考场无字典）；不能跳过全文；不能只记中文。 【步骤】① 读到生词先停半秒看上下文。② 猜测大意后继续。③ A. 立刻查字典打断——低效且不可行，错。④ B. 先猜测再继续 ✓。⑤ C. 跳过全文——夸张，丢失主旨，错。⑥ D. 只记中文——不解决理解，错。 【答案】B. 先猜测再继续。 【易错】见到生词就慌、回头反复读；把时间耗在不影响做题的生词上。 【口诀/模板句】生词先猜继续走，回头再想也来得及；影响做题才细究，别让一词卡全篇。", "steps": ["【秒懂考点】阅读策略：生词先猜", "【第一步】先根据上下文猜测，继续阅读不中断", "【答案】先猜测再继续"]});
  window.STUDY_DATA.questions.push({"id": "e86", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "stem": "“infer” 在阅读题干中通常指（ ）", "options": ["照抄原文", "根据原文推断", "举例说明", "反驳作者"], "answer": "根据原文推断", "pitfalls": ["推断"], "difficulty": 1, "source": "highfreq", "typeLabel": "策略", "video": "v-english", "difficultyLabel": "基础", "tags": ["阅读策略", "ch-en-5"], "explainLevel": "subject-specific", "hint": "【结论】根据原文推断 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：“infer” 在阅读题干中通常指（ ）。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 根据原文推断。 【其他选项为何不对】 • ", "analysis": "【审题】题干：“infer” 在阅读题干中通常指（ ）。考推断题（inference）指令词含义。 【语法点/词汇】infer = 推断、推论，要求根据原文信息得出合理结论，不是照抄。同义指令词：imply（暗示）, suggest, conclude, learn from。 【步骤】① 题干 What can we infer from…？② 任务是依据原文合理推出。③ A. 照抄原文——那是细节题，错。④ B. 根据原文推断 ✓。⑤ C. 举例说明——例证作用，错。⑥ D. 反驳作者——无关，错。 【答案】B. 根据原文推断。 【易错】推断过度（加原文没有的常识）；或原句照搬以为就是推断。原则：有据可依，一步到位，不绝对化。 【口诀/模板句】infer 推断靠原文，有据一步不能玄；照抄细节 infer 异，绝对极端常是坑。", "steps": ["【秒懂考点】infer推断，不是照抄", "【第一步】基于原文推断，答案不会直接写在原文", "【答案】根据原文推断"]});
  window.STUDY_DATA.questions.push({"id": "e87", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "stem": "段落首句通常是（ ）", "options": ["主题句", "举例", "反例", "参考文献"], "answer": "主题句", "pitfalls": ["主题句"], "difficulty": 1, "source": "highfreq", "typeLabel": "策略", "video": "v-english", "difficultyLabel": "基础", "tags": ["阅读策略", "ch-en-5"], "explainLevel": "subject-specific", "hint": "【结论】主题句 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：段落首句通常是（ ）。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 主题句。 【其他选项为何不对】 • B「举例」：语法结构与时态/搭配", "analysis": "【审题】题干：段落首句通常是（ ）。考英语段落结构常识。 【语法点/词汇】学术/说明文段落常见结构：主题句（topic sentence，常在首句）+ 支撑细节/举例/解释。首句概括全段，后文展开。 【步骤】① 英语段落多演绎式：先观点后细节。② 首句通常是主题句。③ A. 主题句 ✓。④ B. 举例——多在主题句之后，错。⑤ C. 反例——更靠后，错。⑥ D. 参考文献——不在段中，错。⑦ 注意：偶尔主题句在末句或隐含，但“通常”首句。 【答案】A. 主题句。 【易错】以为首句是背景/例子；或认为每段首句都是主旨题 【口诀/模板句】段首主题后细节，演绎结构最常见；读段先抓首句意，支撑例子后面跟。", "steps": ["【秒懂考点】首句通常是主题句", "【第一步】段落首句概括段落中心", "【答案】主题句"]});
  window.STUDY_DATA.questions.push({"id": "e90", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "The work is too hard for him ____.", "options": ["to do", "doing", "do", "done"], "answer": "to do", "pitfalls": ["too to"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】to do 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The work is too hard for him ______.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 to d", "analysis": "【审题】题干：The work is too hard for him ______. 考 too…to…（太……而不能）结构。 【语法点/词汇】too + adj. + for sb. + to do（对某人来说太……以致不能）。to do 表结果/程度。 【步骤】① 句型 too hard for him to do。② 工作太难，他做不了。③ A. to do ✓。④ B. doing——too…to 结构用不定式，错。⑤ C. do——缺 to，错。⑥ D. done——被动不合，错。⑦ 同义改写：The work is so hard that he can't do it. 【答案】A. to do。 【易错】与 so…that 从句混淆；或写 too hard for him doing。 【口诀/模板句】too adj. to do 记心间，for sb. 插中间；so…that 可互换，太难以致不能干。", "steps": ["【秒懂考点】too...to...，太……而不能", "【第一步】too hard for him to do，不定式", "【答案】选to do"]});
  window.STUDY_DATA.questions.push({"id": "e91", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "We are proud ____ what we have done.", "options": ["for", "of", "to", "with"], "answer": "of", "pitfalls": ["of固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】of 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：We are proud ______ what we have done.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 of。 【", "analysis": "【审题】题干：We are proud ______ what we have done. 与 be proud of 同一考点，of 后可接 what 从句。 【语法点/词汇】be proud of + 名词/代词/doing/what 从句。what we have done = the things that we have done。 【步骤】① 固定 be proud of。② 代入：proud of what we have done（为我们所做的自豪）。③ A. for——错。④ B. of ✓。⑤ C. to——错。⑥ D. with——错。 【答案】B. of。 【易错】看到从句就想换连接词；或写 proud for。 【口诀/模板句】proud of 不变样，后面名词从句都能装；what 从句当名词，of 仍然站得稳。", "steps": ["【秒懂考点】be proud of，为……自豪", "【第一步】of为我们所做的骄傲", "【答案】选of"]});
  window.STUDY_DATA.questions.push({"id": "e92", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "Please fill the blank with a ____ word.", "options": ["proper", "properly", "property", "propose"], "answer": "proper", "pitfalls": ["形容词"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】proper 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Please fill the blank with a ______ word.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案", "analysis": "【审题】题干：Please fill the blank with a ______ word. 空格修饰 word（名词），需要形容词。 【语法点/词汇】proper 形容词“恰当的”；properly 副词；property 名词“财产”；propose 动词“提议”。冠词 a + 形容词 + 名词。 【步骤】① a ______ word，空格作定语修饰 word。② 词性要形容词。③ A. proper ✓（一个恰当的词）。④ B. properly——副词修饰动词/形容词，不修饰名词，错。⑤ C. property——名词，不能作定语修饰 word（应是 property law），且词义不对，错。⑥ D. propose——动词，错。 【答案】A. proper。 【易错】词形家族混淆（proper/properly/property）；不看句法位置只看词义。 【口诀/模板句】名词前面用形容，动修副来名修形；proper 形 properly 副，词性判断第一步。", "steps": ["【秒懂考点】形容词修饰名词", "【第一步】proper形容词，proper word恰当的词", "【第二步】properly副词，property名词属性", "【答案】选proper"]});
  window.STUDY_DATA.questions.push({"id": "e93", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "The word “maintain” means ____.", "options": ["维护", "破坏", "购买", "测量"], "answer": "维护", "pitfalls": ["词汇"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】维护 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The word “maintain” means ______.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 维护。 【其他选项为", "analysis": "【审题】题干：The word “maintain” means ______. 词义题。 【语法点/词汇】maintain = 维护、保养、维持、坚持（主张）。常见搭配：maintain equipment（维护设备）, maintain a friendship（维持友谊）。 【步骤】① 回忆 maintain 核心义：保持可用/良好状态 → 维护。② A. 维护 ✓。③ B. 破坏（destroy）——反义，错。④ C. 购买（purchase）——无关，错。⑤ D. 测量（measure）——无关，错。 【答案】A. 维护。 【易错】与 maintain 的另一义“主张”混淆后误选；或字面认不出与 main 相关。 【口诀/模板句】maintain 维护又维持，设备系统常用之；destroy 是它反义，测量购买不相干。", "steps": ["【秒懂考点】maintain = 维护、保持", "【第一步】maintain the system维护系统", "【答案】选维护"]});
  window.STUDY_DATA.questions.push({"id": "e95", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "Let's ____ the text together.", "options": ["go over", "go on", "go out", "go up"], "answer": "go over", "pitfalls": ["go短语"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】go over 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Let's ______ the text together.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 go over", "analysis": "【审题】题干：Let's ______ the text together. 考 go 短语动词辨析。 【语法点/词汇】go over = 复习、仔细检查；go on = 继续；go out = 外出/熄灭；go up = 上升。text 课文，together 一起，符合“一起复习课文”。 【步骤】① 语境：一起处理课文 → 复习/过一遍。② A. go over ✓。③ B. go on——go on the text 不表复习，错。④ C. go out——外出，不合，错。⑤ D. go up——上升，错。 【答案】A. go over。 【易错】go 短语互串；或把 over 当“结束”误解。 【口诀/模板句】go over 复习检查，go on 继续不断；go out 出去 go up 涨，短语动词分开看。", "steps": ["【秒懂考点】go over，复习、浏览", "【第一步】go over the text复习课文", "【第二步】go on继续，go out出去，go up上升", "【答案】选go over"]});
  window.STUDY_DATA.questions.push({"id": "e96", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "He is ____ honest man.", "options": ["a", "an", "the", "/"], "answer": "an", "pitfalls": ["看音素"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】an 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He is ______ honest man.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 an。 【其他选项为何不对】 • A「", "analysis": "【审题】题干：He is ______ honest man. 考冠词，honest 首字母 h 不发音。 【语法点/词汇】a/an 的选择看读音（音素）不看字母。honest 读 /ˈɒnɪst/，元音音素开头，用 an。hour, honor, hour 同理。 【步骤】① 看后词 honest 读音：/ɒ/ 开头。② 元音音素 → an。③ A. a——辅音音素才用，错。④ B. an ✓。⑤ C. the——此处泛指“一个诚实的人”，不特指，错。⑥ D. /（零冠词）——可数单数 man 前需冠词，错。 【答案】B. an。 【易错】见 h 字母就用 a；university 用 a（读 /ju:/），hour/honest 用 an。 【口诀/模板句】a an 看音不看形，honest hour 开头元音；university 却是 a，因为 /ju:/ 是辅音素先。", "steps": ["【秒懂考点】honest元音音素开头，用an", "【第一步】an honest man，h不发音，元音开头", "【答案】选an"]});
  window.STUDY_DATA.questions.push({"id": "e98", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "I prefer tea ____ coffee.", "options": ["than", "to", "over", "from"], "answer": "to", "pitfalls": ["to固定"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】to 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：I prefer tea ______ coffee.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 to。 【其他选项为何不对】 •", "analysis": "【审题】题干：I prefer tea ______ coffee. 考 prefer 的介词搭配。 【语法点/词汇】prefer A to B（比起 B 更喜欢 A）；prefer doing to doing；would prefer to do rather than do。 【步骤】① 句型 prefer tea to coffee。② A. than——比较级用 than，但 prefer 不用 than，错。③ B. to ✓。④ C. over——口语偶见 prefer A over B，但标准固定是 to，考试选 to。⑤ D. from——错。 【答案】B. to。 【易错】受“更喜欢”影响选 than；prefer…to 与 compare…with/to 混。 【口诀/模板句】prefer A to B 标准型，不用 than 来不用 from；比起咖啡更爱茶，to 连接两杯拿。", "steps": ["【秒懂考点】prefer A to B，更喜欢A而不是B", "【第一步】prefer tea to coffee，to固定", "【答案】选to"]});
  window.STUDY_DATA.questions.push({"id": "e100", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "stem": "He made a decision ____ accept the job.", "options": ["to", "for", "of", "with"], "answer": "to", "pitfalls": ["不定式"], "difficulty": 1, "source": "highfreq", "typeLabel": "单选", "video": "v-english", "difficultyLabel": "基础", "tags": ["词汇与搭配", "ch-en-1"], "explainLevel": "subject-specific", "hint": "【结论】to 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He made a decision ______ accept the job.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 to", "analysis": "【审题】题干：He made a decision ______ accept the job. 考名词 decision 后的不定式（同位语/定语）。 【语法点/词汇】make a decision to do（决定做）。to do 是 decision 的同位语或后置定语，说明决定内容。类似：make a plan to do, have a chanto do。 【步骤】① decision 表“决定做……”时后接 to do。② to accept the job（接受这份工作）。③ A. to ✓。④ B. for——错。⑤ C. of——错。⑥ D. with——错。 【答案】A. to。 【易错】与 decide to do 混（decide 后直接 to do，decision 是名词要用 a decision to do）。 【口诀/模板句】decision 名词跟 to do，决定内容后面走；decide 动词接 to，名词前加 a decision。", "steps": ["【秒懂考点】decision to do，不定式作定语", "【第一步】decision to accept，决定做某事", "【答案】选to"]});
  window.STUDY_DATA.questions.push({"id": "ex01", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "He ____ a new bike last week.", "options": ["buy", "buys", "bought", "buying"], "answer": "bought", "tags": ["时态"], "source": "batch", "pitfalls": ["不规则"], "explainLevel": "subject-specific", "hint": "【结论】bought 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He ______ a new bike last week.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 bought。 ", "analysis": "【审题】题干：He ______ a new bike last week. last week 明确过去时间，用一般过去时。 【语法点/词汇】一般过去时：动词过去式。buy 的过去式是 bought（不规则，不加 -ed）。 【步骤】① 时间 last week → 一般过去时。② buy → bought。③ A. buy——原形，错。④ B. buys——现在三单，错。⑤ C. bought ✓。⑥ D. buying——非谓语，缺谓语，错。 【答案】C. bought。 【易错】写成 buyed（规则化错误）；或三单 buys 忽略过去时间。 【口诀/模板句】last week 过去式，buy bought 别加 ed；不规则动词表常背，时间标志定时态。", "steps": ["【秒懂考点】last week过去时，buy过去式bought", "【第一步】buy-bought-bought，不规则", "【答案】选bought"]});
  window.STUDY_DATA.questions.push({"id": "ex02", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "She ____ TV when I came in.", "options": ["watched", "is watching", "was watching", "watches"], "answer": "was watching", "tags": ["时态"], "source": "batch", "pitfalls": ["进行时"], "explainLevel": "subject-specific", "hint": "【结论】was watching 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：She ______ TV when I came in.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 was ", "analysis": "【审题】题干：She ______ TV when I came in. when 引导时间状语从句，came in 是过去某刻，主句应为当时正在发生的动作。 【语法点/词汇】过去进行时（was/were doing）+ when + 一般过去时：表示“当……时，正在……”。 【步骤】① 从句 I came in（过去式）。② 主句“她正在看电视”→ was watching。③ A. watched——一般过去，与 when 点状时刻不强调“正在”，错。④ B. is watching——现在进行，时态错。⑤ C. was watching ✓。⑥ D. watches——现在，错。 【答案】C. was watching。 【易错】主从句时态都用一般过去；she 用 were。 【口诀/模板句】when 加过去式，主句 was/were doing；短动作进长动作，正在背景记心中。", "steps": ["【秒懂考点】came in时正在做，过去进行", "【第一步】was watching，when I came in", "【答案】选was watching"]});
  window.STUDY_DATA.questions.push({"id": "ex04", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "She is good ____ singing.", "options": ["in", "at", "on", "for"], "answer": "at", "tags": ["搭配"], "source": "batch", "pitfalls": ["at"], "explainLevel": "subject-specific", "hint": "【结论】at 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：She is good ______ singing.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 at。 【其他选项为何不对】 •", "analysis": "【审题】题干：She is good ______ singing. be good at doing，考介词。 【语法点/词汇】be good at + n./doing（擅长）。singing 是动名词。 【步骤】① 固定 be good at。② A. in——错。③ B. at ✓。④ C. on——错。⑤ D. for——be good for 有益，不合“擅长唱歌”，错。 【答案】B. at。 【易错】good at 与 good for 混；doing 前介词写错。 【口诀/模板句】good at 擅长做，doing 名词都可跟；for 是有益 to 是对人好，三介词义要分好。", "steps": ["【秒懂考点】be good at，擅长", "【第一步】at singing，固定", "【答案】选at"]});
  window.STUDY_DATA.questions.push({"id": "ex05", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "I ____ to school every day.", "options": ["go", "goes", "going", "gone"], "answer": "go", "tags": ["时态"], "source": "batch", "pitfalls": ["时态"], "explainLevel": "subject-specific", "hint": "【结论】go 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：I ______ to school every day.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 go。 【其他选项为何不对】", "analysis": "【审题】题干：I ______ to school every day. every day 表习惯，一般现在时；主语 I 用原形。 【语法点/词汇】一般现在时表习惯/经常性动作。I + 动词原形 go。every day 是标志。 【步骤】① every day → 一般现在。② 主语 I → go（不加 s）。③ A. go ✓。④ B. goes——三单，I 不是三单，错。⑤ C. going——非谓语，错。⑥ D. gone——过去分词，错。 【答案】A. go。 【易错】三单过度使用 goes；every day 与 yesterday 时态混。 【口诀/模板句】every day 现在时，I 后原形不加 s；he she it 才加 es，主谓一致别忽视。", "steps": ["【秒懂考点】every day一般现在时，I用go", "【第一步】go to school，第一人称原形", "【答案】选go"]});
  window.STUDY_DATA.questions.push({"id": "ex10", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "There ____ many students in the classroom.", "options": ["is", "are", "be", "was"], "answer": "are", "tags": ["主谓"], "source": "batch", "pitfalls": ["就近"], "explainLevel": "subject-specific", "hint": "【结论】are 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：There ______ many students in the classroom.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案", "analysis": "【审题】题干：There ______ many students in the classroom. there be 句型，be 与后面名词保持一致。 【语法点/词汇】There be 就近/一致原则：be 的单复数与最近的名词一致；students 复数 → are。many students 前无 a。 【步骤】① 句型 There be。② 表语中心词 students 复数。③ A. is——单数，错。④ B. are ✓。⑤ C. be——原形不能作谓语，错。⑥ D. was——过去时，无过去时间，错。 【答案】B. are。 【易错】就近原则在 a book and two pens 用 is；本句 many students 直接复数用 are。 【口诀/模板句】there be 看后面，单数 is 复数 are；就近原则记在心，two pens and a book 用 is 要分清。", "steps": ["【秒懂考点】there be句型，students复数，are", "【第一步】many students是复数，be用are", "【答案】选are"]});
  window.STUDY_DATA.questions.push({"id": "ex11", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "Can you ____ me your pen?", "options": ["lend", "borrow", "lending", "borrowing"], "answer": "lend", "tags": ["词汇"], "source": "batch", "pitfalls": ["方向"], "explainLevel": "subject-specific", "hint": "【结论】lend 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Can you ______ me your pen?。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 lend。 【其他选项为何不", "analysis": "【审题】题干：Can you ______ me your pen? 考 lend 与 borrow 的方向。 【语法点/词汇】lend sb. sth. = lend sth. to sb.（把……借给某人，借出）；borrow sth. from sb.（从某人借入）。me 是间接宾语，lend 双宾语。 【步骤】① 结构：Can you + 动词 + me + your pen。② “你能把笔借给我吗？”= 你借出 → lend。③ A. lend ✓。④ B. borrow——borrow 应说 borrow your pen from you，不接 me your pen 双宾语表借入，错。⑤ C. lending——can 后原形，错。⑥ D. borrowing——错。 【答案】A. lend。 【易错】中文“借”不分方向；borrow/lend 互换。 【口诀/模板句】lend 借出 borrow 借入，方向不对全糊涂；lend me your pen，borrow from you 记清楚。", "steps": ["【秒懂考点】lend借出，borrow借入，方向相反", "【第一步】you lend me，你借给我，主语you借出", "【第二步】Can后动词原形，lend", "【答案】选lend"]});
  window.STUDY_DATA.questions.push({"id": "ex13", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "My father is ____ engineer.", "options": ["a", "an", "the", "two"], "answer": "an", "tags": ["冠词"], "source": "batch", "pitfalls": ["an"], "explainLevel": "subject-specific", "hint": "【结论】an 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：My father is ______ engineer.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 an。 【其他选项为何不对】", "analysis": "【审题】题干：My father is ______ engineer. engineer 元音音素开头，用 an。 【语法点/词汇】an + 元音音素开头的可数单数。engineer /ˌendʒɪˈnɪə/ 以 /e/ 开头。 【步骤】① engineer 读音元音开头。② 用 an。③ A. a——错。④ B. an ✓。⑤ C. the——此处泛指职业，不特指，错。⑥ D. two——father 是单数，错。 【答案】B. an。 【易错】以字母 e 看形不听音；职业前漏冠词。 【口诀/模板句】engineer 前用 an，元音音素是关键；职业身份说 a/an，特指才把 the 添。", "steps": ["【秒懂考点】engineer元音音素开头，an", "【第一步】engineer发音e开头，用an", "【答案】选an"]});
  window.STUDY_DATA.questions.push({"id": "ex15", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "How ____ is the book? — 20 yuan.", "options": ["many", "much", "old", "long"], "answer": "much", "tags": ["疑问词"], "source": "batch", "pitfalls": ["much"], "explainLevel": "subject-specific", "hint": "【结论】much 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：How ______ is the book? — 20 yuan.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 much。 【", "analysis": "【审题】题干：How ______ is the book? — 20 yuan. 答句是价格，问“多少钱”。 【语法点/词汇】How much 问价格/不可数数量；How many 问可数数量；How old 问年龄；How long 问时长/长度。 【步骤】① 答 20 yuan（价格）→ How much。② A. many——后接可数复数，问数量，错。③ B. much ✓。④ C. old——问年龄，答 years old，错。⑤ D. long——问时间/长度，错。 【答案】B. much。 【易错】much/many 不分；或问价用 how price（错）。 【口诀/模板句】问价多少 how much，可数数量 how many；价格数字 yuan 答，much 开头问价法。", "steps": ["【秒懂考点】问价格how much，不可数", "【第一步】20 yuan，问多少钱，how much", "【第二步】how many问数量，how old年龄，how long长度", "【答案】选much"]});
  window.STUDY_DATA.questions.push({"id": "ex19", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "阅读策略", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "主旨题通常关注（ ）", "options": ["首段与各段首句", "生词表", "页脚", "插图"], "answer": "首段与各段首句", "tags": ["阅读"], "source": "batch", "pitfalls": ["阅读"], "explainLevel": "subject-specific", "hint": "【结论】首段与各段首句 【考点】阅读策略 【一步步怎么算】 ① 句子/题干：主旨题通常关注（ ）。 ② 定位考点：阅读策略。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 首段与各段首句。 【其他选项为何不对】 • B「生词表」：语", "analysis": "【审题】题干：主旨题通常关注（ ）。与 e19 类似，考主旨题阅读焦点。 【语法点/词汇】主旨来源：首段引言、各段首句（topic sentences）、末段总结。生词表/页脚/插图不是主线。 【步骤】① 主旨题找全文中心。② A. 首段与各段首句 ✓。③ B. 生词表——无关，错。④ C. 页脚——无关，错。⑤ D. 插图——辅助，不是主旨，错。 【答案】A. 首段与各段首句。 【易错】被版式元素干扰；主旨看零散细节。 【口诀/模板句】主旨首段段首句，末段收束也可依；插图页脚靠边站，全文中心是第一。", "steps": ["【秒懂考点】主旨题，首段和各段首句", "【语法点/词汇】主旨来源：首段引言、各段首句（topic sentences）、末段总结。生词表/页脚/插图不是主线。", "【步骤】① 主旨题找全文中心。② A. 首段与各段首句 ✓。③ B. 生词表——无关，错。④ C. 页脚——无关，错。⑤ D. 插图——辅助，不是主旨，错。", "【口诀/模板句】主旨首段段首句，末段收束也可依；插图页脚靠边站，全文中心是第一。", "【答案】首段与各段首句"]});
  window.STUDY_DATA.questions.push({"id": "er01", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "I ____ a student.", "options": ["is", "am", "are", "be"], "answer": "am", "tags": ["be"], "source": "batch", "pitfalls": ["be动词"], "explainLevel": "subject-specific", "hint": "【结论】am 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：I ______ a student.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 am。 【其他选项为何不对】 • A「is」：语", "analysis": "【审题】题干：I ______ a student. 主语 I，be 动词用 am。 【语法点/词汇】be 动词现在时：I am / you are / he-she-it is / we-you-they are。 【步骤】① 主语 I。② 对应 am。③ A. is——三单用，错。④ B. am ✓。⑤ C. are——复数/you，错。⑥ D. be——原形，错。 【答案】B. am。 【易错】I 后写 is/are；be 动词缩写形式混淆。 【口诀/模板句】I am you are he is，单数 is 复数 are；be 动词随主语变，表口诀就三句记。", "steps": ["【秒懂考点】I搭配am", "【语法点/词汇】be 动词现在时：I am / you are / he-she-it is / we-you-they are。", "【步骤】① 主语 I。② 对应 am。③ A. is——三单用，错。④ B. am ✓。⑤ C. are——复数/you，错。⑥ D. be——原形，错。", "【口诀/模板句】I am you are he is，单数 is 复数 are；be 动词随主语变，表口诀就三句记。", "【答案】选am"]});
  window.STUDY_DATA.questions.push({"id": "er02", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "She ____ from China.", "options": ["is", "am", "are", "be"], "answer": "is", "tags": ["be"], "source": "batch", "pitfalls": ["is"], "explainLevel": "subject-specific", "hint": "【结论】is 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：She ______ from China.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 is。 【其他选项为何不对】 • B「am", "analysis": "【审题】题干：She ______ from China. 主语 She，be 用 is。 【语法点/词汇】be from = come from。She 三单 → is。 【步骤】① 主语 She 三单 → be 动词用 is。② A. is ✓。③ B. am——配 I，错。④ C. are——配 you/复数，错。⑤ D. be——原形，错。⑥ 翻译：她来自中国。 【答案】A. is。 【易错】she is 缩写 she's；或用 are。 【口诀/模板句】she he it 都用 is，来自某地 is from；I 是 am 你是 are，三个形式要分清。", "steps": ["【秒懂考点】she第三人称单数，is", "【语法点/词汇】be from = come from。She 三单 → is。", "【步骤】① 主语 She 三单 → be 动词用 is。② A. is ✓。③ B. am——配 I，错。④ C. are——配 you/复数，错。⑤ D. be——原形，错。⑥ 翻译：她来自中国。", "【口诀/模板句】she he it 都用 is，来自某地 is from；I 是 am 你是 are，三个形式要分清。", "【答案】选is"]});
  window.STUDY_DATA.questions.push({"id": "er03", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "They ____ happy.", "options": ["is", "am", "are", "be"], "answer": "are", "tags": ["be"], "source": "batch", "pitfalls": ["are"], "explainLevel": "subject-specific", "hint": "【结论】are 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：They ______ happy.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 are。 【其他选项为何不对】 • A「is」：", "analysis": "【审题】题干：They ______ happy. 主语 They（复数），be 动词用 are。 【语法点/词汇】复数主语 + are；happy 是形容词作表语。 【步骤】① 主语 They 复数。② 对应 are。③ A. is——单数，错。④ B. am——只配 I，错。⑤ C. are ✓。⑥ D. be——原形不能作谓语，错。 【答案】C. are。 【易错】they is；或把 are 缩写 're 忘记还原。 【口诀/模板句】we you they 全用 are，复数主语统一它；单数 is I am，三句口诀不会差。", "steps": ["【秒懂考点】they复数，are", "【语法点/词汇】复数主语 + are；happy 是形容词作表语。", "【步骤】① 主语 They 复数。② 对应 are。③ A. is——单数，错。④ B. am——只配 I，错。⑤ C. are ✓。⑥ D. be——原形不能作谓语，错。", "【口诀/模板句】we you they 全用 are，复数主语统一它；单数 is I am，三句口诀不会差。", "【答案】选are"]});
  window.STUDY_DATA.questions.push({"id": "er04", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "He ____ to work by bus.", "options": ["go", "goes", "going", "gone"], "answer": "goes", "tags": ["时态"], "source": "batch", "pitfalls": ["goes"], "explainLevel": "subject-specific", "hint": "【结论】goes 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He ______ to work by bus.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 goes。 【其他选项为何不对】", "analysis": "【审题】题干：He ______ to work by bus. 主语 He 三单，一般现在时，动词加 -es（go→goes）。 【语法点/词汇】一般现在时三单：动词 + s/es。go 以 o 结尾 → goes。by bus 表方式。 【步骤】① He 三单，习惯动作。② go → goes。③ A. go——缺 -es，错。④ B. goes ✓。⑤ C. going——非谓语，错。⑥ D. gone——过去分词，错。 【答案】B. goes。 【易错】go 加 s 写成 gos（应为 goes）；I/you 后误加 s。 【口诀/模板句】he she it 动词加 s，go 结尾 o 加 es；goes to work by bus，三单变化要落实。", "steps": ["【秒懂考点】he第三人称单数，一般现在时goes", "【第一步】go to work，he goes", "【答案】选goes"]});
  window.STUDY_DATA.questions.push({"id": "er05", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "Birds can ____.", "options": ["fly", "flying", "flew", "flies"], "answer": "fly", "tags": ["情态"], "source": "batch", "pitfalls": ["can原形"], "explainLevel": "subject-specific", "hint": "【结论】fly 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Birds can ______.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 fly。 【其他选项为何不对】 • B「flyin", "analysis": "【审题】题干：Birds can ______. 情态动词 can 后接动词原形。 【语法点/词汇】can/could/will/would/should/may/might/must + 动词原形（不带 to）。 【步骤】① can 后用原形 fly。② A. fly ✓。③ B. flying——错。④ C. flew——过去式，错。⑤ D. flies——三单，错。 【答案】A. fly。 【易错】can 后用 to fly 或 flying；flies 拼写（fly→flies）。 【口诀/模板句】情态动词跟原形，can may will must 清；后头不带 to 也不变，fly 原形最标准。", "steps": ["【秒懂考点】can后动词原形", "【第一步】Birds can fly，鸟会飞", "【答案】选fly"]});
  window.STUDY_DATA.questions.push({"id": "er06", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "The book ____ on the desk.", "options": ["is", "am", "are", "be"], "answer": "is", "tags": ["be"], "source": "batch", "pitfalls": ["is"], "explainLevel": "subject-specific", "hint": "【结论】is 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The book ______ on the desk.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 is。 【其他选项为何不对】 ", "analysis": "【审题】题干：The book ______ on the desk. 主语 The book 单数，be 用 is。 【语法点/词汇】单数主语 + is；on the desk 是地点状语。 【步骤】① The book 三单单数。② A. is ✓。③ B. am——只配 I，错。④ C. are——复数，错。⑤ D. be——原形，错。 【答案】A. is。 【易错】there be 与主系表混；book 后写 are。 【口诀/模板句】the book 单数用 is，主系表里 be 随主语；一本书在桌上，is 站在名词后。", "steps": ["【秒懂考点】book单数，is", "【语法点/词汇】单数主语 + is；on the desk 是地点状语。", "【步骤】① The book 三单单数。② A. is ✓。③ B. am——只配 I，错。④ C. are——复数，错。⑤ D. be——原形，错。", "【口诀/模板句】the book 单数用 is，主系表里 be 随主语；一本书在桌上，is 站在名词后。", "【答案】选is"]});
  window.STUDY_DATA.questions.push({"id": "er13", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "They ____ students.", "options": ["is", "am", "are", "be"], "answer": "are", "tags": ["be"], "source": "batch", "pitfalls": ["are"], "explainLevel": "subject-specific", "hint": "【结论】are 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：They ______ students.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 are。 【其他选项为何不对】 • A「i", "analysis": "【审题】题干：They ______ students. 主语 They，be 用 are。 【语法点/词汇】They + are；students 是表语。 【步骤】① They 复数。② A. is——错。③ B. am——错。④ C. are ✓。⑤ D. be——错。 【答案】C. are。 【易错】there are 与 they are 混；或漏 be。 【口诀/模板句】they are students 对，主语复数 are 跟；I am he is they are，三个搭配不能混。", "steps": ["【秒懂考点】they are，复数", "【语法点/词汇】They + are；students 是表语。", "【步骤】① They 复数。② A. is——错。③ B. am——错。④ C. are ✓。⑤ D. be——错。", "【口诀/模板句】they are students 对，主语复数 are 跟；I am he is they are，三个搭配不能混。", "【答案】选are"]});
  window.STUDY_DATA.questions.push({"id": "er14", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "I ____ TV now.", "options": ["watch", "watched", "am watching", "watches"], "answer": "am watching", "tags": ["时态"], "source": "batch", "pitfalls": ["am watching"], "explainLevel": "subject-specific", "hint": "【结论】am watching 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：I ______ TV now.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 am watching。 【其他选项", "analysis": "【审题】题干：I ______ TV now. now 是现在进行时标志。 【语法点/词汇】现在进行时：am/is/are + doing。I + am watching。 【步骤】① now → 现在进行。② I → am watching。③ A. watch——一般现在，错。④ B. watched——过去，错。⑤ C. am watching ✓。⑥ D. watches——三单一般现在，错。 【答案】C. am watching。 【易错】now 用一般现在；I 后用 is watching。 【口诀/模板句】now look listen 用进行，be doing 结构清；I am watching TV now，标志词把时态定。", "steps": ["【秒懂考点】now现在进行时，am watching", "【语法点/词汇】现在进行时：am/is/are + doing。I + am watching。", "【步骤】① now → 现在进行。② I → am watching。③ A. watch——一般现在，错。④ B. watched——过去，错。⑤ C. am watching ✓。⑥ D. watches——三单一般现在，错。", "【口诀/模板句】now look listen 用进行，be doing 结构清；I am watching TV now，标志词把时态定。", "【答案】am watching"]});
  window.STUDY_DATA.questions.push({"id": "er15", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "时态与语态", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "He ____ to school yesterday.", "options": ["go", "goes", "went", "going"], "answer": "went", "tags": ["时态"], "source": "batch", "pitfalls": ["went"], "explainLevel": "subject-specific", "hint": "【结论】went 【考点】时态与语态 【一步步怎么算】 ① 句子/题干：He ______ to school yesterday.。 ② 定位考点：时态与语态。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 went。 【其他选项", "analysis": "【审题】题干：He ______ to school yesterday. yesterday 是过去时间，用一般过去时。 【语法点/词汇】go 的过去式 went（不规则）。 【步骤】① yesterday → 过去时。② go → went。③ A. go——错。④ B. goes——现在三单，错。⑤ C. went ✓。⑥ D. going——错。 【答案】C. went。 【易错】goed（不存在）；yesterday 漏过去式。 【口诀/模板句】yesterday 用过去式，go went 不规则；went to school 表昨天，时间副词定时态。", "steps": ["【秒懂考点】yesterday过去时，go过去式went", "【语法点/词汇】go 的过去式 went（不规则）。", "【步骤】① yesterday → 过去时。② go → went。③ A. go——错。④ B. goes——现在三单，错。⑤ C. went ✓。⑥ D. going——错。", "【口诀/模板句】yesterday 用过去式，go went 不规则；went to school 表昨天，时间副词定时态。", "【答案】went"]});
  window.STUDY_DATA.questions.push({"id": "er16", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "The sun ____ in the east.", "options": ["rise", "rises", "rose", "rising"], "answer": "rises", "tags": ["时态"], "source": "batch", "pitfalls": ["rises"], "explainLevel": "subject-specific", "hint": "【结论】rises 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：The sun ______ in the east.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 rises。 【其他选项为", "analysis": "【审题】题干：The sun ______ in the east. 客观真理，一般现在时；主语 sun 三单。 【语法点/词汇】rise 升起，三单 rises；in the east 表地点。科学事实用一般现在。 【步骤】① 太阳从东方升起是真理。② 一般现在 + 三单 → rises。③ A. rise——缺 -s，错。④ B. rises ✓。⑤ C. rose——过去，真理不用过去，错。⑥ D. rising——非谓语，错。 【答案】B. rises。 【易错】rise/raise 不分（raise 及物）；三单 -s 漏。 【口诀/模板句】真理事实现在时，sun rises 三单 s；rise 不及物 raise 及物，东方升起用 rises。", "steps": ["【秒懂考点】客观真理，一般现在时，sun第三人称rises", "【语法点/词汇】rise 升起，三单 rises；in the east 表地点。科学事实用一般现在。", "【步骤】① 太阳从东方升起是真理。② 一般现在 + 三单 → rises。③ A. rise——缺 -s，错。④ B. rises ✓。⑤ C. rose——过去，真理不用过去，错。⑥ D. rising——非谓语，错。", "【口诀/模板句】真理事实现在时，sun rises 三单 s；rise 不及物 raise 及物，东方升起用 rises。", "【答案】rises"]});
  window.STUDY_DATA.questions.push({"id": "er17", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "Please open ____ door.", "options": ["a", "an", "the", "this"], "answer": "the", "tags": ["冠词"], "source": "batch", "pitfalls": ["the"], "explainLevel": "subject-specific", "hint": "【结论】the 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Please open ______ door.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 the。 【其他选项为何不对】 • ", "analysis": "【审题】题干：Please open ______ door. 双方共知的门（那扇门），用定冠词 the。 【语法点/词汇】the 表特指（双方都知道或上文提到）；a/an 泛指。open the door 是常见祈使句。 【步骤】① 语境是“把门打开”，特指眼前那扇门。② 用 the。③ A. a——泛指一扇，错。④ B. an——错。⑤ C. the ✓。⑥ D. this——this door 也说得通，但祈使句 open the door 是固定说法，且 the 最中性标准，本题 【答案】C. the。 【易错】a door（随便一扇）与 the door（那扇）混；this 强于 the。 【口诀/模板句】特指双方都知道，定冠词 the 要用好；open the door 祈使句，眼前那扇不用 a。", "steps": ["【秒懂考点】特指双方知道的门，the", "【语法点/词汇】the 表特指（双方都知道或上文提到）；a/an 泛指。open the door 是常见祈使句。", "【步骤】① 语境是“把门打开”，特指眼前那扇门。② 用 the。③ A. a——泛指一扇，错。④ B. an——错。⑤ C. the ✓。⑥ D. this——this door 也说得通，但祈使句 open the door 是固定说法，且 the 最中性标准，本题答案 the。", "【口诀/模板句】特指双方都知道，定冠词 the 要用好；open the door 祈使句，眼前那扇不用 a。", "【答案】the"]});
  window.STUDY_DATA.questions.push({"id": "er19", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "I have ____ apple and ____ banana.", "options": ["a;a", "an;a", "the;the", "an;an"], "answer": "an;a", "tags": ["冠词"], "source": "batch", "pitfalls": ["an;a"], "explainLevel": "subject-specific", "hint": "【结论】an;a 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：I have ______ apple and ______ banana.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 an;", "analysis": "【审题】题干：I have ______ apple and ______ banana. 两个不定冠词分别修饰 apple、banana。 【语法点/词汇】apple 元音音素 /æ/ → an；banana 辅音 /b/ → a。并列各配各的冠词。 【步骤】① apple → an。② banana → a。③ 合成 an apple and a banana。④ A. a;a——apple 应 an，错。⑤ B. an;a ✓。⑥ C. the;the——非特指，错。⑦ D. an;an——banana 应 a，错。 【答案】B. an;a。 【易错】并列名词共用一个冠词；或 banana 也写 an。 【口诀/模板句】apple 元音 an 打头，banana 辅音 a 跟走；并列各自配冠词，an apple and a banana。", "steps": ["【秒懂考点】apple元音an，banana辅音a", "【语法点/词汇】apple 元音音素 /æ/ → an；banana 辅音 /b/ → a。并列各配各的冠词。", "【步骤】① apple → an。② banana → a。③ 合成 an apple and a banana。④ A. a;a——apple 应 an，错。⑤ B. an;a ✓。⑥ C. the;the——非特指，错。⑦ D. an;an——banana 应 a，错。", "【口诀/模板句】apple 元音 an 打头，banana 辅音 a 跟走；并列各自配冠词，an apple and a banana。", "【答案】an;a"]});
  window.STUDY_DATA.questions.push({"id": "er23", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "Let's ____ football.", "options": ["play", "plays", "playing", "to play"], "answer": "play", "tags": ["非谓语"], "source": "batch", "pitfalls": ["play"], "explainLevel": "subject-specific", "hint": "【结论】play 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Let's ______ football.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 play。 【其他选项为何不对】 • ", "analysis": "【审题】题干：Let's ______ football. Let's = Let us，后接动词原形（省略 to 的不定式）。 【语法点/词汇】let sb. do sth.（让某人做）；Let's do = 让我们一起做。play football 踢足球。 【步骤】① Let's 后用原形 play。② A. play ✓。③ B. plays——三单，错。④ C. playing——错。⑤ D. to play——let 后不带 to，错。 【答案】A. play。 【易错】Let's to play；或 Let's playing。 【口诀/模板句】let's 后面用原形，to 不能往中间停；Let's play football，邀请建议一起行。", "steps": ["【秒懂考点】Let's后动词原形，play", "【语法点/词汇】let sb. do sth.（让某人做）；Let's do = 让我们一起做。play football 踢足球。", "【步骤】① Let's 后用原形 play。② A. play ✓。③ B. plays——三单，错。④ C. playing——错。⑤ D. to play——let 后不带 to，错。", "【口诀/模板句】let's 后面用原形，to 不能往中间停；Let's play football，邀请建议一起行。", "【答案】play"]});
  window.STUDY_DATA.questions.push({"id": "er24", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "Thank you ____ your help.", "options": ["for", "of", "to", "at"], "answer": "for", "tags": ["搭配"], "source": "batch", "pitfalls": ["for"], "explainLevel": "subject-specific", "hint": "【结论】for 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Thank you ______ your help.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 for。 【其他选项为何不对】", "analysis": "【审题】题干：Thank you ______ your help. 考 thank 的介词。 【语法点/词汇】Thank you for sth./doing（因……感谢）。for 表原因。 【步骤】① 感谢原因 → for。② A. for ✓。③ B. of——错。④ C. to——thank to 不表感谢原因，错。⑤ D. at——错。 【答案】A. for。 【易错】Thanks to（多亏）与 Thank you for 混。 【口诀/模板句】thank you for 表原因，多亏是 thanks to 两回事；your help 是感谢对象，for 跟在 thanks 后。", "steps": ["【秒懂考点】Thank you for，为……感谢", "【语法点/词汇】Thank you for sth./doing（因……感谢）。for 表原因。", "【步骤】① 感谢原因 → for。② A. for ✓。③ B. of——错。④ C. to——thank to 不表感谢原因，错。⑤ D. at——错。", "【口诀/模板句】thank you for 表原因，多亏是 thanks to 两回事；your help 是感谢对象，for 跟在 thanks 后。", "【答案】for"]});
  window.STUDY_DATA.questions.push({"id": "er25", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "Listen! Someone ____ singing.", "options": ["is", "are", "am", "be"], "answer": "is", "tags": ["时态"], "source": "batch", "pitfalls": ["is"], "explainLevel": "subject-specific", "hint": "【结论】is 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Listen! Someone ______ singing.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 is。 【其他选项为何不", "analysis": "【审题】题干：Listen! Someone ______ singing. Listen! 现在进行时；someone 单数，be 用 is。 【语法点/词汇】现在进行时 am/is/are + doing。someone/everyone/no one 作主语视为单数。 【步骤】① Listen! → 进行时。② Someone 单数 → is singing。③ A. is ✓。④ B. are——someone 后不用 are，错。⑤ C. am——只配 I，错。⑥ D. be——原形，错。 【答案】A. is。 【易错】someone 被当复数用 are；Listen 用一般现在。 【口诀/模板句】Listen! Look! 用进行，someone 单数 is 顶；someone is singing 正在唱，复合不定代词看作单。", "steps": ["【秒懂考点】Listen! 现在进行，someone单数is", "【语法点/词汇】现在进行时 am/is/are + doing。someone/everyone/no one 作主语视为单数。", "【步骤】① Listen! → 进行时。② Someone 单数 → is singing。③ A. is ✓。④ B. are——someone 后不用 are，错。⑤ C. am——只配 I，错。⑥ D. be——原形，错。", "【口诀/模板句】Listen! Look! 用进行，someone 单数 is 顶；someone is singing 正在唱，复合不定代词看作单。", "【答案】is"]});
  window.STUDY_DATA.questions.push({"id": "enx2", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "She ____ her homework last night.", "options": ["does", "did", "do", "doing"], "answer": "did", "tags": ["时态"], "source": "batch", "pitfalls": ["did"], "explainLevel": "subject-specific", "hint": "【结论】did 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：She ______ her homework last night.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 did。 【其", "analysis": "【审题】题干：She ______ her homework last night. last night 过去时间，一般过去时；do→did。 【语法点/词汇】do 的过去式 did；her homework 作宾语。 【步骤】① last night → 过去时。② do → did。③ A. does——现在三单，错。④ B. did ✓。⑤ C. do——原形，错。⑥ D. doing——错。 【答案】B. did。 【易错】did 后又加 s；或用 have done（无 for/since）。 【口诀/模板句】last night 用 did，do did done 三级记；did her homework 表做完，一般过去最合适。", "steps": ["【秒懂考点】last night过去，do过去式did", "【语法点/词汇】do 的过去式 did；her homework 作宾语。", "【步骤】① last night → 过去时。② do → did。③ A. does——现在三单，错。④ B. did ✓。⑤ C. do——原形，错。⑥ D. doing——错。", "【口诀/模板句】last night 用 did，do did done 三级记；did her homework 表做完，一般过去最合适。", "【答案】did"]});
  window.STUDY_DATA.questions.push({"id": "enx3", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "There ____ a book and two pens on the desk.", "options": ["is", "are", "be", "am"], "answer": "is", "tags": ["主谓"], "source": "batch", "pitfalls": ["is"], "explainLevel": "subject-specific", "hint": "【结论】is 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：There ______ a book and two pens on the desk.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案", "analysis": "【审题】题干：There ______ a book and two pens on the desk. there be 就近原则，靠近 be 的是 a book（单数）。 【语法点/词汇】There be 就近一致：be 与最近的名词一致。a book 单数 → is。 【步骤】① there be 句型。② 最近名词 a book 单数。③ A. is ✓。④ B. are——被 two pens 干扰，但就近原则用 is，错。⑤ C. be——原形，错。⑥ D. am——错。 【答案】A. is。 【易错】只看 two pens 用 are；忽略就近原则。 【口诀/模板句】there be 就近看，a book and two pens 用 is；two pens and a book 才用 are，位置先后定单双。", "steps": ["【秒懂考点】there be就近，a book单数is", "【语法点/词汇】There be 就近一致：be 与最近的名词一致。a book 单数 → is。", "【步骤】① there be 句型。② 最近名词 a book 单数。③ A. is ✓。④ B. are——被 two pens 干扰，但就近原则用 is，错。⑤ C. be——原形，错。⑥ D. am——错。", "【口诀/模板句】there be 就近看，a book and two pens 用 is；two pens and a book 才用 are，位置先后定单双。", "【答案】is"]});
  window.STUDY_DATA.questions.push({"id": "enx4", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "He is ____ than his brother.", "options": ["tall", "taller", "tallest", "more tall"], "answer": "taller", "tags": ["比较级"], "source": "batch", "pitfalls": ["taller"], "explainLevel": "subject-specific", "hint": "【结论】taller 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：He is ______ than his brother.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 taller。 【", "analysis": "【审题】题干：He is ______ than his brother. than 是比较级标志。 【语法点/词汇】tall → taller（单音节加 -er）。than 前必须比较级。 【步骤】① than → 比较级。② tall → taller。③ A. tall——原级，错。④ B. taller ✓。⑤ C. tallest——最高级，错。⑥ D. more tall——tall 单音节不用 more，错。 【答案】B. taller。 【易错】more tall（错）；tall 与 short 逻辑反了（题干就是 taller）。 【口诀/模板句】than 前比较级，单音节加 er 多音节 more；tall taller tallest，三级变化要熟悉。", "steps": ["【秒懂考点】than比较级，taller", "【语法点/词汇】tall → taller（单音节加 -er）。than 前必须比较级。", "【步骤】① than → 比较级。② tall → taller。③ A. tall——原级，错。④ B. taller ✓。⑤ C. tallest——最高级，错。⑥ D. more tall——tall 单音节不用 more，错。", "【口诀/模板句】than 前比较级，单音节加 er 多音节 more；tall taller tallest，三级变化要熟悉。", "【答案】taller"]});
  window.STUDY_DATA.questions.push({"id": "enx5", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "This is ____ interesting film.", "options": ["a", "an", "the", "two"], "answer": "an", "tags": ["冠词"], "source": "batch", "pitfalls": ["an"], "explainLevel": "subject-specific", "hint": "【结论】an 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：This is ______ interesting film.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 an。 【其他选项为何", "analysis": "【审题】题干：This is ______ interesting film. interesting 以元音音素 /ɪ/ 开头，用 an。 【语法点/词汇】an + 元音音素；interesting /ˈɪntrəstɪŋ/。 【步骤】① interesting 元音音素开头。② an。③ A. a——错。④ B. an ✓。⑤ C. the——此处是泛指“一部有趣的电影”，this is an… 是介绍，错。⑥ D. two——单数 film，错。 【答案】B. an。 【易错】interesting 以 i 字母看成辅音；或写 a interesting。 【口诀/模板句】interesting 元音开头 an，音素原则记心间；a university a hour 对比记，看音不看字母面。", "steps": ["【秒懂考点】interesting元音，an", "【语法点/词汇】an + 元音音素；interesting /ˈɪntrəstɪŋ/。", "【步骤】① interesting 元音音素开头。② an。③ A. a——错。④ B. an ✓。⑤ C. the——此处是泛指“一部有趣的电影”，this is an… 是介绍，错。⑥ D. two——单数 film，错。", "【口诀/模板句】interesting 元音开头 an，音素原则记心间；a university a hour 对比记，看音不看字母面。", "【答案】an"]});
