  window.STUDY_DATA.questions.push({"id": "enx14", "module": "public", "subject": "英语", "chapter": "ch-en-4", "knowledgePoint": "非谓语动词", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "I want ____ a doctor when I grow up.", "options": ["be", "to be", "being", "been"], "answer": "to be", "tags": ["非谓语"], "source": "batch", "pitfalls": ["to be"], "explainLevel": "subject-specific", "hint": "【结论】to be 【考点】非谓语动词 【一步步怎么算】 ① 句子/题干：I want ______ a doctor when I grow up.。 ② 定位考点：非谓语动词。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 to", "analysis": "【审题】题干：I want ______ a doctor when I grow up. want to do sth. 【语法点/词汇】want to do（想做）。grow up 长大。 【步骤】① want to do。② to be a doctor（成为医生）。③ A. be——缺 to，错。④ B. to be ✓。⑤ C. being——错。⑥ D. been——错。 【答案】B. to be。 【易错】want doing（英式“需要被”）与 want to do 混。 【口诀/模板句】want to do 想要做，to be 名词职业跟；want 一般接 to do，to be a doctor 表长大后的身份。", "steps": ["【秒懂考点】want to be想成为，to be", "【语法点/词汇】want to do（想做）。grow up 长大。", "【步骤】① want to do。② to be a doctor（成为医生）。③ A. be——缺 to，错。④ B. to be ✓。⑤ C. being——错。⑥ D. been——错。", "【口诀/模板句】want to do 想要做，to be 名词职业跟；want 一般接 to do，to be a doctor 表长大后的身份。", "【答案】to be"]});
  window.STUDY_DATA.questions.push({"id": "enx15", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "词汇与搭配", "type": "single", "typeLabel": "单选", "difficulty": 1, "difficultyLabel": "基础", "stem": "Please turn ____ the light. It's dark.", "options": ["on", "off", "up", "down"], "answer": "on", "tags": ["短语"], "source": "batch", "pitfalls": ["on"], "explainLevel": "subject-specific", "hint": "【结论】on 【考点】词汇与搭配 【一步步怎么算】 ① 句子/题干：Please turn ______ the light. It's dark.。 ② 定位考点：词汇与搭配。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 on。", "analysis": "【审题】题干：Please turn ______ the light. It's dark. 天黑需要开灯，turn on（打开）。 【语法点/词汇】turn on 打开（电器）；turn off 关闭；turn up 调大；turn down 调小/拒绝。 【步骤】① It's dark → 需要开灯。② turn on the light。③ A. on ✓。④ B. off——关灯与 dark 矛盾，错。⑤ C. up——调大亮度通常说 turn up the light 也可，但“开灯”标准是 turn on，且 dark 明确需要打开，错。⑥ D. down——调小，错。 【答案】A. on。 【易错】turn on/off/up/down 四短语互串；dark 不看语境乱选 off。 【口诀/模板句】turn on 开 turn off 关，turn up 大 turn down 小；It's dark 开灯用 on，电器开关成对记。", "steps": ["【秒懂考点】turn on打开，天黑开灯", "【语法点/词汇】turn on 打开（电器）；turn off 关闭；turn up 调大；turn down 调小/拒绝。", "【步骤】① It's dark → 需要开灯。② turn on the light。③ A. on ✓。④ B. off——关灯与 dark 矛盾，错。⑤ C. up——调大亮度通常说 turn up the light 也可，但“开灯”标准是 turn on，且 dark 明确需要打开，错。⑥ D. down——调小，错。", "【口诀/模板句】turn on 开 turn off 关，turn up 大 turn down 小；It's dark 开灯用 on，电器开关成对记。", "【答案】on"]});
