  window.STUDY_DATA.questions.push({"id": "ew01", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "翻译与写作", "type": "write", "typeLabel": "写作", "difficulty": 2, "difficultyLabel": "强化", "stem": "书面表达（约 80 词）：给同学写一封电子邮件，建议他如何提高英语阅读能力。（说明理由与具体做法）", "answer": "范文见 sample", "accept": ["自评"], "sample": "Dear Li Hua,\n\nI am sorry to hear that you find English reading difficult. Here is my advice.\n\nFirst, read a little every day. Even ten minutes can make a difference. Second, choose passages that are neither too easy nor too difficult, and guess the meaning of new words from the context. Third, keep a notebook and write down the useful words and sentences you meet.\n\nI hope these suggestions can help you. If you need more help, just write to me.\n\nBest wishes,\nZhang Wei", "scorePoints": ["格式：称呼+正文+落款", "至少 2 条具体建议并有展开", "时态与人称一致", "约 80 词，无重大语法错误", "有衔接词 First/Second/Finally"], "pitfalls": ["邮件格式"], "tags": ["写作", "建议信"], "source": "highfreq", "score": 20, "explainLevel": "subject-specific", "hint": "【结论】范文见 sample 【考点】翻译与写作 【一步步怎么算】 ① 句子/题干：书面表达（约 80 词）：给同学写一封电子邮件，建议他如何提高英语阅读能力。（说明理由与具体做法）。 ② 定位考点：翻译与写作。 ③ 用规则排除错误时态/语", "analysis": "【审题】题干：书面表达（约 80 词）：给同学写一封电子邮件，建议他如何提高英语阅读能力。（说明理由与具体做法） 【语法点/词汇】邮件格式：Dear…, / 正文 / Best wishes；建议句型：You should… / I suggest… / It's helpful to…；阅读策略：read every day, guess new words, take notes。 【步骤】① 开头：Dear Li Hua, I'm glad to hear from you. ② 引出：You asked me how to improve reading. ③ 建议1：You should read English every day（每天读）。④ 建议2：Try to guess new words from context（猜生词）。⑤ 建议3：Take notes of useful phrases（记短语）。⑥ 结尾：I hope these tips help. Best wishes, Wang Ming。⑦ 约80词，格式完整。 【答案】范文见 sample。范文：Dear Li Hua, I'm glad to hear from you. You asked me how to improve your English reading. Here are my suggestions. First, you should read English for 20 minutes every day. Second, try to guess new words from the context instead of looking them up. Third, take notes of useful phrases and review them. If you keep practicing, your reading will get better soon. Best wishes, Wang Ming. 【易错】漏邮件格式；建议不具体；词数不足。 【口诀/模板句】邮件开头 Dear，建议 You should/I suggest；具体做法三条走，结尾 Best wishes 收。", "steps": ["【秒懂考点】写作：建议邮件，结构要点", "【第一步】开头Dear，表明目的提高阅读", "【第二步】具体建议：每天读、猜词、多读不同话题", "【第三步】结尾鼓励，落款", "【范文】见参考答案"]});
  window.STUDY_DATA.questions.push({"id": "ew02", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "翻译与写作", "type": "write", "typeLabel": "写作", "difficulty": 2, "difficultyLabel": "强化", "stem": "书面表达（约 80 词）：介绍你的专业（移动互联应用技术）以及你为什么选择它。", "answer": "范文见 sample", "accept": ["自评"], "sample": "My major is Mobile Internet Application Technology. I chose this major for two reasons.\n\nFirst, mobile apps are widely used in our daily life and business, so this field has a bright future. Second, I am deeply interested in computers and programming.\n\nIn this program, I learn programming languages, app design and network technology. I also take part in small projects with my classmates, which helps me put what I have learned into practice.\n\nIn the future, I hope to become a qualified app developer and create useful apps that make people's life easier.", "scorePoints": ["专业名称准确", "说明 2 点原因/课程", "未来打算", "条理清晰", "词数约 80"], "pitfalls": ["条理"], "tags": ["写作", "介绍"], "source": "highfreq", "score": 20, "explainLevel": "subject-specific", "hint": "【结论】范文见 sample 【考点】翻译与写作 【一步步怎么算】 ① 句子/题干：书面表达（约 80 词）：介绍你的专业（移动互联应用技术）以及你为什么选择它。。 ② 定位考点：翻译与写作。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确", "analysis": "【审题】题干：书面表达（约 80 词）：介绍你的专业（移动互联应用技术）以及你为什么选择它。 【语法点/词汇】专业名 Mobile Internet Application Technology；选择原因：interested in, good at, future job；结构：介绍专业 → 原因 → 打算。 【步骤】① 开头：My major is Mobile Internet Application Technology. ② 介绍：It is about apps and mobile networks. ③ 原因1：I am interested in computers. ④ 原因2：I want to be a developer. ⑤ 结尾：I will study hard to achieve my dream. ⑥ 约80词，条理清楚。 【答案】范文见 sample。范文：My major is Mobile Internet Application Technology. It is about mobile apps and networks. I chose it because I am interested in computers and the Internet. Also, this field has many job chances. In the future, I want to be a good app developer. I will study hard and practimore to achieve my dream. 【易错】专业名译错；原因不充分；条理乱。 【口诀/模板句】介绍专业 My major is，选择原因 because I am interested；job chances 工作机会，结尾 study hard 梦想。", "steps": ["【秒懂考点】写作：介绍专业，结构", "【第一步】开头点明专业，移动互联应用技术", "【第二步】原因：兴趣、就业前景、实用", "【第三步】未来打算", "【范文】见参考答案"]});
  window.STUDY_DATA.questions.push({"id": "ew04", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "翻译与写作", "type": "write", "typeLabel": "写作", "difficulty": 2, "difficultyLabel": "强化", "stem": "书面表达（约 80 词）：以 “A useful app” 为题写短文，介绍一个对你学习有帮助的应用。", "answer": "范文见 sample", "accept": ["自评"], "sample": "A Useful App\n\nThe app I use most is a flashcard tool. It helps me review English words and computer terms every day.\n\nI can make my own word lists and set a study plan. The app reminds me to review the words I have almost forgotten, which makes my memory more efficient. Besides, I can learn anywhere, on the bus, in the library, or before bed.\n\nThanks to this app, I have remembered hundreds of new words. I think it is really a helpful tool for study, and I strongly recommend it to my classmates.", "scorePoints": ["标题", "介绍功能", "个人体验/好处", "结尾评价", "词数约 80"], "pitfalls": ["说明顺序"], "tags": ["写作"], "source": "highfreq", "score": 20, "explainLevel": "subject-specific", "hint": "【结论】范文见 sample 【考点】翻译与写作 【一步步怎么算】 ① 句子/题干：书面表达（约 80 词）：以 “A useful app” 为题写短文，介绍一个对你学习有帮助的应用。 ② 定位考点：翻译与写作。 ③ 用规则排除错误时态/", "analysis": "【审题】题干：书面表达（约 80 词）：以 “A useful app” 为题写短文，介绍一个对你学习有帮助的应用。 【语法点/词汇】说明顺序：名称 → 功能 → 好处；useful 有用的；help me with…。 【步骤】① 开头：A useful app. ② 名称：My favorite app is Ximalaya. ③ 功能：I can listen to English on it. ④ 好处：It helps me improve listening. ⑤ 结尾：It is really useful for my study. ⑥ 约80词，说明顺序清晰。 【答案】范文见 sample。范文：A useful app. My favorite app is Ximalaya. I can listen to English stories and news on it every day. It helps me improve my listening and speaking. When I meet new words, I can also look them up quickly. The app is free and easy to use. It is really useful for my study, and I will keep using it. 【易错】只写名称不写好处；条理乱。 【口诀/模板句】说明顺序：名称功能好处；I can/heps me 讲作用；A useful app 题目，study useful 收尾。", "steps": ["【秒懂考点】写作：介绍有用的应用", "【第一步】点明应用名称和功能", "【第二步】为什么有用、怎么帮助学习", "【第三步】推荐", "【范文】见参考答案"]});
  window.STUDY_DATA.questions.push({"id": "ex21", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "翻译与写作", "type": "write", "typeLabel": "写作", "difficulty": 2, "difficultyLabel": "强化", "stem": "书面表达（约 80 词）：介绍你的家乡。", "answer": "范文见 sample", "sample": "My hometown is Guilin, a beautiful city in the north of Guangxi. It is famous for its clear rivers and green hills, which attract visitors from all over the world.\n\nThe people there are friendly and warm-hearted, and life is peaceful and comfortable. The local food, such as rice noodles, is delicious. When I am free, I like walking along the riverside and enjoying the beautiful scenery.\n\nI love my hometown deeply, and I hope you can visit it one day.", "scorePoints": ["地点与特点", "个人感受", "结构完整", "约 80 词"], "tags": ["写作"], "source": "batch", "score": 20, "pitfalls": ["条理"], "explainLevel": "subject-specific", "hint": "【结论】范文见 sample 【考点】翻译与写作 【一步步怎么算】 ① 句子/题干：书面表达（约 80 词）：介绍你的家乡。。 ② 定位考点：翻译与写作。 ③ 用规则排除错误时态/语态/搭配。 ④ 正确答案是 范文见 sample。 【易错", "analysis": "【审题】题干：书面表达（约 80 词）：介绍你的家乡。 【语法点/词汇】结构：位置 → 人口/风景 → 特产/人 → 感情；be located in, be famous for, friendly。 【步骤】① 开头：My hometown is Guilin. ② 位置：It is in the north of Guangxi. ③ 风景：It is famous for its beautiful mountains and rivers. ④ 人：People there are friendly. ⑤ 结尾：I love my hometown very much. ⑥ 约80词，条理清楚。 【答案】范文见 sample。范文：My hometown is Guilin. It is in the north of Guangxi. It is famous for its beautiful mountains and rivers. Every year, many tourists come to visit it. The food there is also very delicious. People in my hometown are friendly and hard-working. I love my hometown very much, and I hope it will become better and better. 【易错】只写地点不写风景；条理乱；漏感情。 【口诀/模板句】介绍家乡：位置风景特产人；be famous for 有名，I love my hometown 感情。", "steps": ["【秒懂考点】写作：介绍家乡，结构", "【第一步】地理位置", "【第二步】特色：风景、食物、人", "【第三步】感情", "【范文】见参考答案"], "accept": ["范文见 sample"]});
  window.STUDY_DATA.questions.push({"id": "enx37", "module": "public", "subject": "英语", "chapter": "ch-en-5", "knowledgePoint": "翻译与写作", "type": "write", "typeLabel": "写作", "difficulty": 2, "difficultyLabel": "强化", "stem": "书面表达（约 80 词）：My Plan for the Winter Vacation（寒假计划）", "answer": "范文见 sample", "sample": "My Plan for the Winter Vacation\n\nThe winter vacation is coming. To make it meaningful and enjoyable, I have made a careful plan.\n\nFirst, I will spend two hours every morning reviewing my lessons and finishing my homework. Second, I plan to read two English books and keep an English diary every day so that I can improve my writing. Third, I will take exercise for an hour every afternoon to keep healthy. Besides, I will help my parents with housework and visit my grandparents.\n\nI am sure I will have a full and happy winter vacation.", "scorePoints": ["时间安排", "至少 3 条计划", "结构完整", "约 80 词"], "tags": ["写作"], "source": "batch", "score": 20, "pitfalls": ["范文见sample"], "explainLevel": "subject-specific", "hint": "【结论】范文见 sample 【考点】翻译与写作 【一步步怎么算】 ① 句子/题干：书面表达（约 80 词）：My Plan for the Winter Vacation（寒假计划）。 ② 定位考点：翻译与写作。 ③ 用规则排除错误时态/", "analysis": "【审题】题干：书面表达（约 80 词）：My Plan for the Winter Vacation（寒假计划）。 【语法点/词汇】计划句型：I will… / I am going to… / I plan to…；学习/锻炼/娱乐/家务。 【步骤】① 开头：The winter vacation is coming. I have made a plan. ② 学习：I will finish my homework first. ③ 锻炼：I will do sports every day. ④ 家务：I will help my parents with housework. ⑤ 娱乐：I will read some books. ⑥ 结尾：I am sure I will have a meaningful vacation. ⑦ 约80词。 【答案】范文见 sample。范文：My Plan for the Winter Vacation. The winter vacation is coming. I have made a plan. First, I will finish my homework carefully. Second, I will do sports every day to keep healthy. Third, I will help my parents with housework. I also plan to read some useful books. I am sure I will have a meaningful and happy vacation. 【易错】只写一件事；无顺序词；词数不够。 【口诀/模板句】计划 will/going to，顺序 First Second Third；学习锻炼家务读，meaningful vacation 收。", "steps": ["【秒懂考点】写作：寒假计划，时间顺序安排", "【语法点/词汇】计划句型：I will… / I am going to… / I plan to…；学习/锻炼/娱乐/家务。", "【步骤】① 开头：The winter vacation is coming. I have made a plan. ② 学习：I will finish my homework first. ③ 锻炼：I will do sports every day. ④ 家务：I will help my parents with housework. ⑤ 娱乐：I will read some books. ⑥ 结尾：I am sure I will have a meaningful vacation. ⑦ 约80词。", "【口诀/模板句】计划 will/going to，顺序 First Second Third；学习锻炼家务读，meaningful vacation 收。", "【答案】范文见sample"], "accept": ["范文见 sample"]});

