  window.STUDY_DATA.questions.push({"id": "mock-en-001", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "—Tom, are these books ? —No, they are . Mine are on that shelf.", "options": ["mine; Jenny", "yours; Jenny's", "mine; Jenny's", "yours; Jenny"], "answer": "yours; Jenny's", "pitfalls": ["mine 意为\"我的\"，与答句\"No(不是我的)\"语义相反", "Jenny 是普通名词不能直接表所属"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】B 【考点】名词性物主代词与所有格 【一步步怎么算】yours=your books（你的书），第二空 Jenny's=Jenny's books（珍妮的书），都省略了后面的名词，须用名词性物主代词/所有格。 故答案为 B。", "analysis": "【审题】题干：—Tom, are these books ? —No, they are . Mine are on that shelf。本句考查名词性物主代词与所有格。 【语法点/词汇】名词分可数与不可数。常见不可数名词：advice(建议)、water/juice(水/果汁)、paper(纸)、music(音乐)、bread(面包)、information(信息)、work(工作)、news(消息)、money(钱)、furniture(家具)。不可数名词表数量要用量词 a pieof / two glasses of / three pairs of，本身不加 s。名词复数：potato→potatoes、tomato→tomatoes(有生命的o加es)；German→Germans、Englishman→Englishmen；mouse→mice；sheep/deer/fish 单复数同形。所有格：有生命用 's（Tom's），无生命用 of；双重所有格 a friend of my father's。名词作定语用单数（concert tickets、shoe shop）。共同所有 A and B's（共一个），各自所有 A's and B's（各一个）。 【步骤】① 定位考点：名词性物主代词与所有格。② yours=your books（你的书），第二空 Jenny's=Jenny's books（珍妮的书），都省略了后面的名词，须用名词性物主代词/所有格。 ③ 由此确定答案为 B。 【答案】B. yours; Jenny's 【易错】mine 意为\"我的\"，与答句\"No(不是我的)\"语义相反；Jenny 是普通名词不能直接表所属。 【口诀/模板句】不可数，量词加；有生命o加es；中日瑞不变，英法变，其余s加后面；共同所有加最后，各自所有都加's。", "steps": []});
