  window.STUDY_DATA.questions.push({"id": "mock-en-031", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "My shoes brown. This new pair of blue shoes my sister's.", "options": ["1s; 1s", "is; are", "are; is", "are;are"], "answer": "are; is", "pitfalls": ["pair of 短语真正的中心词是 pair，别被后面的复数名词带偏"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】C 【考点】主谓一致 【一步步怎么算】shoes 复数用 are；this pair of 作主语，谓语与 pair 一致用 is，故 are; is。 故答案为 C。", "analysis": "【审题】题干：My shoes brown. This new pair of blue shoes my sister's。本句考查主谓一致。 【语法点/词汇】情态动词：can't 表\"不可能\"（否定推测）；must 表\"必须\"，mustn't 表\"禁止、不准\"；needn't 表\"不必\"。need/dare 作情态动词多用于否定/疑问，作实义动词用 need to do / don't need to do、dare to do。not only...but also 连接主语时，谓语就近一致（与 but also 后的名词一致）。this pair of + 名词作主语，谓语与 pair 一致（单数）。return 不与 back 连用（语义重复）。be from = come from。瞬间动词（put on）与延续动词（wear）有别。感官/系动词：sound（听起来）、look（看起来）、smell（闻起来）、feel（摸起来）后接形容词。动词短语：give up（放弃）、put off（推迟）、turn down（调小/拒绝）、get up（起床）、put out（扑灭）、discover（发现已存在之物）、invent（发明前所未有之物）、win + 比赛/奖牌、beat + 人/队。动词+副词结构中，代词放中间（wake him up、put it off）。 【步骤】① 定位考点：主谓一致。② shoes 复数用 are；this pair of 作主语，谓语与 pair 一致用 is，故 are; is。 ③ 由此确定答案为 C。 【答案】C. are; is 【易错】pair of 短语真正的中心词是 pair，别被后面的复数名词带偏。 【口诀/模板句】can't 不可能 mustn't 禁止 needn't 不必；not only...but also 就近找；return 不跟 back；put on 动作 wear 状态；动副短语代词夹中间。", "steps": []});
