  window.STUDY_DATA.questions.push({"id": "mock-en-121", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "Mom won't let Dick go out he promises to be back by 10: 00 tonight.", "options": ["if", "when", "since", "unless"], "answer": "unless", "pitfalls": ["unless 表\"除非\"，引导条件状语从句"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】D 【考点】unless 除非 【一步步怎么算】除非答应十点前回来，否则不让出去，用 unless（=if not）。 故答案为 D。", "analysis": "【审题】题干：Mom won't let Dick go out he promises to be back by 10: 00 tonight。本句考查unless 除非。 【语法点/词汇】if（如果/是否）、unless（除非=if not）、though/although（虽然，不与 but 连用）、because（因为，不与 so 连用）、while（当…时/而）、when（当…时）、as soon as（一…就）、until（直到，not...until 直到…才）、as long as（只要）、whenever（无论何时）。so...that 中 so 后接形容词/副词，such...that 中 such 后接名词短语（so many/much/few/little 除外）。whether...or not 固定，if 一般不与 or not 直接连用。并列连词：both...and、neither...nor、either...or、not only...but also。祈使句 + and/or + 陈述句。否定句中并列用 or（不用 and）。 【步骤】① 定位考点：unless 除非。② 除非答应十点前回来，否则不让出去，用 unless（=if not）。 ③ 由此确定答案为 D。 【答案】D. unless 【易错】unless 表\"除非\"，引导条件状语从句。 【口诀/模板句】if 如果 unless 除非；though 不搭 but because 不搭 so；so 形 such 名；not until 直到才；否定并列用 or。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-en-122", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "you must go and play football, at least wait until school is over.", "options": ["If", "Whether", "Unless", "So that"], "answer": "If", "pitfalls": ["if 引导条件", "unless 与句意相反"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】A 【考点】if 如果 【一步步怎么算】如果你一定要去踢球，至少等到放学，用 If。 故答案为 A。", "analysis": "【审题】题干：you must go and play football, at least wait until school is over。本句考查if 如果。 【语法点/词汇】if（如果/是否）、unless（除非=if not）、though/although（虽然，不与 but 连用）、because（因为，不与 so 连用）、while（当…时/而）、when（当…时）、as soon as（一…就）、until（直到，not...until 直到…才）、as long as（只要）、whenever（无论何时）。so...that 中 so 后接形容词/副词，such...that 中 such 后接名词短语（so many/much/few/little 除外）。whether...or not 固定，if 一般不与 or not 直接连用。并列连词：both...and、neither...nor、either...or、not only...but also。祈使句 + and/or + 陈述句。否定句中并列用 or（不用 and）。 【步骤】① 定位考点：if 如果。② 如果你一定要去踢球，至少等到放学，用 If。 ③ 由此确定答案为 A。 【答案】A. If 【易错】if 引导条件；unless 与句意相反。 【口诀/模板句】if 如果 unless 除非；though 不搭 but because 不搭 so；so 形 such 名；not until 直到才；否定并列用 or。", "steps": []});
