  window.STUDY_DATA.questions.push({"id": "mock-en-151", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "We have geography lesson in the afternoon. I think it's useful subject.", "options": ["aja", "anja", "an; an", "a;an"], "answer": "aja", "pitfalls": ["看发音：useful 虽以元音字母 u 开头，但读 /j/ 是辅音音素，用 a"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】A 【考点】a/an 用法 【一步步怎么算】geography 以 /dʒ/ 辅音开头用 a，useful 以 /j/ 辅音开头用 a，故 a; a。 故答案为 A。", "analysis": "【审题】题干：We have geography lesson in the afternoon. I think it's useful subject。本句考查a/an 用法。 【语法点/词汇】a 用在以辅音音素开头的词前，an 用在以元音音素开头的词前——看发音而非字母。字母按其读音判断：\"h\"读 /eɪtʃ/（元音开头）用 an，\"u\"读 /juː/（辅音开头）用 a；ID 读 /ˌaɪˈdiː/（元音开头）用 an；useful 以 /j/ 开头用 a。the 表特指（双方都知道的、被定语限定的、上文提过的、独一无二的）。序数词前通常加 the；但前面已有形容词性物主代词/名词所有格时不加 the。零冠词：三餐、球类运动、学科、称呼前；乐器前加 the（play the piano）。play chess（棋类零冠词）。 【步骤】① 定位考点：a/an 用法。② geography 以 /dʒ/ 辅音开头用 a，useful 以 /j/ 辅音开头用 a，故 a; a。 ③ 由此确定答案为 A。 【答案】A. aja 【易错】看发音：useful 虽以元音字母 u 开头，但读 /j/ 是辅音音素，用 a。 【口诀/模板句】a 辅 an 元看发音；h 用 an、u 用 a、ID 用 an；特指用 the；棋类三餐零冠词，乐器前面要加 the。", "steps": []});
