  window.STUDY_DATA.questions.push({"id": "mock-en-181", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "useful invention the computer is!", "options": ["What a", "What an", "Howa", "How an"], "answer": "What a", "pitfalls": ["useful 虽元音字母开头但读 /j/ 辅音，用 a"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】A 【考点】What a/an 【一步步怎么算】useful 以 /j/ 辅音开头，What a useful invention（名词短语用 what）。 故答案为 A。", "analysis": "【审题】题干：useful invention the computer is!。本句考查What a/an。 【语法点/词汇】What 引导：What a/an + 形容词 + 可数名词单数（+主谓）；What + 形容词 + 可数名词复数/不可数名词（+主谓）。How 引导：How + 形容词/副词（+主谓）。判断关键看主语前的词是名词还是形容词/副词。注意 useful 以 /j/ 辅音开头用 a；amazing 以元音开头用 an。have a good time、a fantastic time 是固定短语。 【步骤】① 定位考点：What a/an。② useful 以 /j/ 辅音开头，What a useful invention（名词短语用 what）。 ③ 由此确定答案为 A。 【答案】A. What a 【易错】useful 虽元音字母开头但读 /j/ 辅音，用 a。 【口诀/模板句】What 名 How 形副；单数 a/an 别忘记，复数不可数直接加；useful 用 a，amazing 用 an。", "steps": []});
