  window.STUDY_DATA.questions.push({"id": "mock-en-241", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "—Could you go shopping with me? —I'm not sure. But I'll tell you as soon as I my homework.", "options": ["finish", "finished", "will finish", "am going to finish"], "answer": "finish", "pitfalls": ["从句不用 will finish，用一般现在时"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】A 【考点】主将从现 【一步步怎么算】as soon as 引导时间从句，主句将来、从句用一般现在时 finish。 故答案为 A。", "analysis": "【审题】题干：—Could you go shopping with me? —I'm not sure. But I'll tell you as soon as I my homework。本句考查主将从现。 【语法点/词汇】时间/条件状语从句遵循\"主将从现\"：主句将来时，从句用一般现在时（as soon as、when、if、unless）。现在完成时表过去动作对现在的影响或持续到现在，标志 for+时间段、since、already、yet、ever、so far、over the last... years。瞬间动词（buy、die、begin、join、come、go、leave）不能与 for+时间段连用，要换成相应的延续状态：buy→have、die→be dead、begin→be on、join→be in、leave→be away。\"情态动词 + have done\"表对过去的推测：must have done（一定）、can't have done（不可能）。make/see/hear/let sb do，主动省略 to，变被动要补 to（be made to do）。被动语态 be + 过去分词；现在进行时被动 is being done。have sth done 让别人做某事。it is + 时间段 + since... 用现在完成时。 【步骤】① 定位考点：主将从现。② as soon as 引导时间从句，主句将来、从句用一般现在时 finish。 ③ 由此确定答案为 A。 【答案】A. finish 【易错】从句不用 will finish，用一般现在时。 【口诀/模板句】主将从现；for sin用完成；瞬间动词不能接 for，buy→have、die→be dead、begin→be on；主动省 to 被动补 to；被动 be+过分。", "steps": []});
