  window.STUDY_DATA.questions.push({"id": "mock-en-361", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语专项", "type": "single", "typeLabel": "单选", "stem": "一 Sorry, Daddy. I am not getting on well with my studies. 一 Well. you hadn't wasted so much time playing online games.", "options": ["Asif", "Evenif", "Ifonly", "Only if"], "answer": "Ifonly", "pitfalls": ["If only 表愿望", "Only if 表条件"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语专项", "迁入"], "hint": "【结论】C 【考点】If only 【一步步怎么算】If only you hadn't wasted（要是…就好了，过去虚拟）。 故答案为 C。", "analysis": "【审题】题干：一 Sorry, Daddy. I am not getting on well with my studies. 一 Well. you hadn't wasted so much time playing online games。本句考查If only。 【语法点/词汇】if 虚拟：与现在相反（从句 did/were，主句 would do）；与过去相反（从句 had done，主句 would have done）；与将来相反（从句 were to do/should do，主句 would do）。错综时间虚拟分别看时间。if 省略则从句倒装（Were I/Had I/Should I）。含蓄虚拟：without、but for、otherwise、or 引导。If only（要是…就好了）；as if（好像）。表示\"建议、命令、要求、重要\"的词（suggest, require, order, demand, advisable, necessary, important, strange）后的名词性从句用 (should) + 动词原形；It is strange that ... should（竟然）。 【步骤】① 定位考点：If only。② If only you hadn't wasted（要是…就好了，过去虚拟）。 ③ 由此确定答案为 C。 【答案】C. Ifonly 【易错】If only 表愿望；Only if 表条件。 【口诀/模板句】现在 did/were，过去 had done，将来 were to do；if 省略要倒装；without/otherwise 含蓄虚拟；建议命令要求用 (should) do。", "steps": []});
