  window.STUDY_DATA.questions.push({"id": "mock-enjing-001", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "I need ____ of paper to write a letter.", "options": ["a piece", "a bar", "a loaf", "a bottle"], "answer": "a piece", "pitfalls": ["误选 a bar（一条，用于肥皂/巧克力）", "误选 a loaf（一条，用于面包）", "误选 a bottle（一瓶）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "paper（纸）是不可数名词，用 a pieof 表示“一张”，选 A。", "analysis": "【考点】不可数名词的“量词”搭配。paper 表示“纸”时是不可数名词，不能直接说 a paper，要借助“单位量词 + of”结构。 【量词辨析】 • a pieof 表示“一张/一片/一块”，搭配 paper、bread、news、advi等； • a bar of 表示“一条/一块”，搭配 soap、chocolate； • a loaf of 表示“一条（面包）”，搭配 bread； • a bottle of 表示“一瓶”，搭配液体。 【步骤】 ① 空格后是 paper（纸），不可数； ② “一张纸”的固定搭配是 a pieof paper； ③ 故选 A。 【答案】A。 【口诀】纸张用 piece，面包一条 loaf，肥皂一块 bar，液体一瓶 bottle。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-002", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "This book is ____ great value. It helps me a lot.", "options": ["in", "with", "for", "of"], "answer": "of", "pitfalls": ["误选 in（be in 是“穿着/处于”）", "误选 with（be with 是“和……一起”）", "误选 for（be for 是“为了/支持”）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "“be of + 抽象名词”表示“具有某种性质”，be of great value = 很有价值，选 D。", "analysis": "【考点】“be of + 抽象名词”结构。该结构表示“具有某种性质或特征”，相当于 be + 该名词对应的形容词。 【结构】be of great value = be very valuable（很有价值）；类似的还有 be of importan= be important（重要）、be of help = be helpful（有帮助）、be of use = be useful（有用）。 【步骤】 ① 句意为“这本书很有价值，对我帮助很大”； ② great value 是抽象名词，要表达“有价值”用 be of value； ③ 故选 D。 【答案】D。 【口诀】of 加抽象名词，等于对应形容词：of value = valuable。", "steps": []});
