  window.STUDY_DATA.questions.push({"id": "mock-enjing-011", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "I have something ____ to tell you.", "options": ["interesting", "interested", "interest", "interests"], "answer": "interesting", "pitfalls": ["误选 interested（指人“感兴趣的”，不修饰物）", "误选 interest（名词/动词，不能后置修饰 something）", "误选 interests（第三人称单数）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "修饰事物 something 用 -ing 形容词 interesting（有趣的）；interested 修饰人，选 A。", "analysis": "【考点】-ing 与 -ed 形容词的区别。 【规则】 • interesting（令人感兴趣的、有趣的），通常修饰事物； • interested（感到感兴趣的），通常修饰人，常搭配 be interested in。 此外，形容词修饰不定代词 something、anything、nothing 时要后置。 【步骤】 ① 空格修饰 something（事物），表示“有趣的事”； ② 修饰事物用 -ing 形容词 interesting； ③ something interesting 表示“有趣的事”，选 A。 【答案】A。 【口诀】-ing 修饰物（令人……），-ed 修饰人（感到……）；形容词修饰不定代词要后置。", "steps": []});
