  window.STUDY_DATA.questions.push({"id": "mock-enjing-022", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "He ____ for three hours.", "options": ["has left", "has been away", "left", "goes away"], "answer": "has been away", "pitfalls": ["误选 has left（leave 是短暂动词，不能与 for 三小时连用）", "误选 left（一般过去时不搭配 for 表持续到现在）", "误选 goes away（时态和延续性都不对）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "for three hours 是一段时间，要搭配延续性状态；be away 可延续，用 has been away，选 B。", "analysis": "【考点】延续性动词与“for + 时间段”连用。 【规则】for three hours 表示持续了一段时间，要求谓语动词或状态是可延续的。leave（离开）是短暂/非延续性动词，不能与表示一段时间的 for 短语连用；be away（离开的状态）是可延续的，可用 has been away。 【转换】短暂动词 → 延续状态：leave → be away；buy → have；borrow → keep；die → be dead；join → be in/be a member。 【步骤】 ① for three hours 表持续，排除短暂动词 leave 相关的 A、C； ② 用可延续的 be away，现在完成时 has been away； ③ 选 B。 【答案】B。 【口诀】for + 时间段配延续，leave 要换成 be away。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-023", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "____ we go shopping this weekend?", "options": ["Will", "Shall", "Do", "Are"], "answer": "Shall", "pitfalls": ["误选 Will（Will we… 不用于礼貌提建议）", "误选 Do（一般现在时不表建议）", "误选 Are（are 后不能接动词原形 go）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "shall 用于第一人称(I/we)的疑问句表示提出建议或征求意见，选 B。", "analysis": "【考点】shall 表建议/征求意见。 【规则】Shall I / Shall we…? 用于第一人称疑问句，表示“我（们）做……好吗？”，是提出建议、征求对方意见的常用句型。 【辨析】 • Shall we go shopping?（我们去购物好吗？）表建议； • Will you…? 用于请求对方； • Let's… 是直接提建议。 【步骤】 ① 主语是 we，句末 this weekend 表将来； ② 第一人称疑问句提建议用 Shall； ③ 选 B。 【答案】B。 【口诀】Shall I/we 提建议，Will you 请对方。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-024", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "I love reading novels. — So ____ I.", "options": ["am", "do", "have", "will"], "answer": "do", "pitfalls": ["误选 am（前句没有 be 动词，不能用 am）", "误选 have（前句不是完成时）", "误选 will（前句不是将来时）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "“So + 助动词 + 主语”表示“……也一样”；前句是一般现在时实义动词 love，助动词用 do，选 B。", "analysis": "【考点】倒装结构 So + 助动词/情态动词/be + 主语。 【规则】“So + 助动词 + 主语”表示“前面说的情况也适用于后者”，即“……也一样”。所用助动词要与前一句的时态和动词类型保持一致： • 前句是实义动词的一般现在时 → 用 do/does； • 前句是 be 动词 → 用 am/is/are； • 前句是完成时 → 用 have/has； • 前句有情态动词 → 用同一情态动词。 【步骤】 ① 前句 I love reading novels 是一般现在时、实义动词 love； ② 对应的助动词是 do； ③ So do I（我也是），选 B。 【答案】B。 【口诀】So + 助动词 + 主语，助动词跟前句时态走。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-025", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "It is the second time that I ____ to Beijing.", "options": ["have been", "had been", "am", "was"], "answer": "have been", "pitfalls": ["误选 had been（只有主句是 It was the…time 时才用过去完成时）", "误选 am（been to 表示去过）", "误选 was"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "“It/This is the + 序数词 + time that…”从句要用现在完成时，选 have been。", "analysis": "【考点】固定句型中的现在完成时。 【规则】 • It/This is the first/second/third time that + 主语 + have/has done（现在完成时），表示“这是第几次做某事”； • 若主句是 It was the … time，则 that 从句用过去完成时 had done。 【辨析】have been to 表示“去过（已回来）”；have gone to 表示“去了（还没回来）”。 【步骤】 ① 主句是 It is the second time（现在时）； ② that 从句要用现在完成时，主语 I 用 have been； ③ 选 A。 【答案】A。 【口诀】is the 序数词 time，从句现在完成时；was 则用过去完成时。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-026", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "She quickly ____ at her watch and realized she was late.", "options": ["looked", "glanced", "glimpsed", "saw"], "answer": "glanced", "pitfalls": ["误选 looked（look at 是一般看，不强调快速）", "误选 glimpsed（glimpse 是“无意中瞥见”，多作及物动词，不搭配 at）", "误选 saw（see 强调结果，不接 at）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "glanat 强调“匆匆一看、扫视”，quickly 提示快速瞥一眼，选 B。", "analysis": "【考点】“看”的近义动词辨析。 【辨析】 • look at 强调“看”的动作，是普通用语； • glanat 强调“粗略、匆匆地看一眼、扫视”，常与 quickly 连用； • glimpse 指“无意中瞥见”，多作及物动词（catch a glimpse of）； • see 强调“看见”的结果，及物动词。 【步骤】 ① 副词 quickly 强调动作快； ② 空格后有 at，且是匆匆看表，用 glanat； ③ 选 B。 【答案】B。 【口诀】glanat 匆匆一瞥，look at 一般看，see 重结果，glimpse 无意瞥见。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-027", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "____ the sight of the police, the thief ran away immediately.", "options": ["In", "At", "On", "With"], "answer": "At", "pitfalls": ["误选 In（in sight 表示“在视野内”）", "误选 On", "误选 With"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "at the sight of 是固定搭配，表示“一看见……（就）”，选 B。", "analysis": "【考点】固定短语 at the sight of。 【规则】at the sight of 表示“一看见……就……”，介词用 at。 【辨析】 • in sight 表示“看得见、在视野内”；out of sight 表示“看不见”； • at the sight of 强调“看到的瞬间”的反应。 【步骤】 ① 句意为“小偷一看到警察就立刻跑了”； ② “一看见”用 at the sight of； ③ 选 B。 【答案】B。 【口诀】at the sight of 一看见，in sight 看得见。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-028", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "He earns his ____ by working in a factory and gets paid by the hour.", "options": ["income", "wage", "salary", "pay"], "answer": "wage", "pitfalls": ["误选 salary（salary 是按月发的“薪水”，多指白领）", "误选 income（income 是“收入”总称，范围太广）", "误选 pay（pay 泛指报酬，不突出按小时）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "gets paid by the hour（按小时计酬）、在工厂做工，对应 wage（按小时/周发的工资），选 B。", "analysis": "【考点】“工资/收入”近义词辨析。 【辨析】 • wage（常用复数 wages）指按小时、日、周或计件发给体力劳动者的“工资”，如 get paid by the hour； • salary 指按月或更长周期发给职员、专业人员的“薪水”； • income 指“收入”的总称（包括工资、投资等）； • pay 是“报酬、工资”的通用词。 【步骤】 ① “在工厂工作、按小时计酬”符合 wage 的用法； ② 选 B（wage）。 【答案】B。 【口诀】蓝领按周/小时是 wage，白领按月是 salary，收入总称 income。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-029", "module": "public", "subject": "英语", "chapter": "ch-en-4", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "She has the ____ to solve this difficult problem.", "options": ["ability", "capacity", "both A and B", "neither A nor B"], "answer": "ability", "pitfalls": ["误选 capacity（capacity 多指“容量、容纳/承受能力”，常搭配 for）", "误选 both（两词侧重不同，此处 ability 更贴切）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "ability to do sth. 指“做某事的能力（尤指通过技能能做到）”；have the ability to do 是固定搭配，选 A。", "analysis": "【考点】ability 与 capacity 辨析。 【辨析】 • ability 指“能力、本领”，强调通过学习、技能能够做某事，结构为 the ability to do sth.； • capacity 多指“容量、容纳力”，也指“接受/理解的潜力”，常搭配 for（capacity for sth.）； • capable 是形容词，搭配 be capable of。 【步骤】 ① 句意为“她有能力解决这道难题”，强调实际能做到； ② 后接 to solve，用 the ability to do； ③ 选 A。 【答案】A。 【口诀】ability to do（能力），capacity for（容量/潜力）。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-030", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "He talked about the teachers and the school ____ he had visited.", "options": ["who", "that", "which", "about which"], "answer": "that", "pitfalls": ["误选 who（who 只能指人，不能指 school）", "误选 which（which 只能指物，不能指 teachers）", "误选 about which（visit 是及物动词，不需要 about）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "先行词同时有人(teachers)和物(school)，关系代词用 that，选 B。", "analysis": "【考点】定语从句中 that 的用法。 【规则】当先行词同时包含“人”和“物”时，关系代词用 that（that 既可指人也可指物）。 【分析】句中先行词是 the teachers and the school（既有“人”又有“物”），关系词在从句中作 visit 的宾语，用 that。 【步骤】 ① 先行词 teachers（人）+ school（物）； ② 关系代词需同时指人和物，用 that； ③ visit 为及物动词，直接作宾语，选 B。 【答案】B。 【口诀】先行词人物并列，关系代词用 that。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-031", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "I want to buy the same dress ____ she is wearing.", "options": ["as", "that", "which", "what"], "answer": "as", "pitfalls": ["误选 that（the same…that 指“同一件”，本句是买一样的，用 as）", "误选 which", "误选 what（what 不引导定语从句）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "the same…as 是固定搭配，表示“和……一样的”，as 引导定语从句，选 A。", "analysis": "【考点】the same…as 定语从句。 【辨析】 • the same … as 表示“和……一样的（同类事物，并非同一个）”，as 是关系代词； • the same … that 表示“正是那一个（同一个事物）”。 本句是“想买和她穿的一样的裙子”，是同类而非同一件，用 as。 【步骤】 ① 句中有 the same； ② 买的是“同款”，用 the same…as； ③ 选 A。 【答案】A。 【口诀】the same…as 同款，the same…that 同一件。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-032", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "Such students ____ work hard will surely succeed.", "options": ["who", "that", "as", "which"], "answer": "as", "pitfalls": ["误选 who（有 such 时固定用 as）", "误选 that（such…that 是结果状语，that 不充当成分）", "误选 which"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "such…as 是固定搭配，as 引导定语从句并在从句中作主语，选 C。", "analysis": "【考点】such…as 引导定语从句。 【辨析】 • such … as 中 as 是关系代词，引导定语从句，并在从句中作主语或宾语； • such … that 中 that 引导结果状语从句，that 不充当句子成分。 本句从句缺主语（work hard），故用 as，相当于“那些努力学习的学生”。 【步骤】 ① 句首有 Such，空格后从句 work hard 缺主语； ② 引导定语从句且作主语用 as； ③ 选 C。 【答案】C。 【口诀】such…as 定从（as 作成分），such…that 结果（that 不作成分）。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-033", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "He smokes as expensive a cigarette ____ he can afford.", "options": ["as", "that", "which", "what"], "answer": "as", "pitfalls": ["误选 that", "误选 which", "误选 what"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "as…as 引导定语从句，意为“和……一样”，后一个 as 是关系代词作 afford 的宾语，选 A。", "analysis": "【考点】as…as 引导定语从句。 【规则】“as + 形容词 + a/an + 名词 + as”结构中，前一个 as 是副词，后一个 as 是关系代词，引导定语从句并在从句中作宾语，意为“和……一样”。 【分析】as expensive a cigarette as he can afford = 他能负担得起的最贵的烟；后一个 as 作 afford 的宾语。 【步骤】 ① 句中出现 as expensive…as 结构； ② 后一个 as 引导定语从句、作 afford 的宾语； ③ 选 A。 【答案】A。 【口诀】as…as 中后一个 as 作关系代词，可在从句中作宾语。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-034", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "— ____ you do, I will support you.", "options": ["However", "Whenever", "Whatever", "Wherever"], "answer": "Whatever", "pitfalls": ["误选 However（however 修饰形容词/副词，不直接作宾语）", "误选 Whenever（whenever 表时间，不搭配 do）", "误选 Wherever（wherever 表地点）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "空格作 do 的宾语（“无论你做什么”），用 Whatever，选 C。", "analysis": "【考点】让步状语从句的引导词。 【辨析】 • Whatever = No matter what，在从句中作主语或宾语（“无论什么”）； • However = No matter how，修饰形容词或副词（“无论多么”）； • Whenever 表时间（“无论何时”）；Wherever 表地点（“无论何地”）。 【步骤】 ① 从句中 do 是及物动词，缺宾语； ② “无论做什么”用 Whatever（作 do 的宾语）； ③ 选 C。 【答案】C。 【口诀】Whatever 作宾语/主语，However 修饰形/副。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-035", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "It will be three days ____ he comes back.", "options": ["when", "before", "after", "since"], "answer": "before", "pitfalls": ["误选 when（when 不用于此句型）", "误选 after（after 表“之后”，语义相反）", "误选 since（sin主句多用完成时）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "“It will be + 时间段 + before…”表示“要过多久才……”，选 B。", "analysis": "【考点】before 引导时间状语从句的固定句型。 【规则】 • It will/would be + 时间段 + before…，肯定形式表示“要过……才……”； • It won't be long before… 表示“过不了多久就……”。 【步骤】 ① 句意为“要过三天他才会回来”； ② 用 It will be three days before… 结构； ③ 选 B。 【答案】B。 【口诀】It will be 时间 before…，“要过多久才”；not long before“很快就”。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-036", "module": "public", "subject": "英语", "chapter": "ch-en-2", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "____ he is young, he has made great achievements in his field.", "options": ["As", "Though", "Although", "All of the above"], "answer": "All of the above", "pitfalls": ["以为 As 不能表让步（Young as he is 倒装可表让步）", "以为 Although 不能用（although 可正常引导）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "as/though/although 都可表“虽然、尽管”（as 需倒装），三个都能引导，选 D。", "analysis": "【考点】让步状语从句引导词。 【辨析】 • although、though 正常引导，although 语气更正式，不与 but 连用； • as 引导让步状语从句时要用倒装：Young as he is = Though he is young（尽管他年轻）； • though 也可用于倒装。 【步骤】 ① 句意为“尽管他年轻，却已在领域内取得巨大成就”； ② although、though 可直接引导；as 用倒装（Young as he is）也可； ③ 三者都可，选 D。 【答案】D。 【口诀】although/though 正常用，as 让步要倒装。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-037", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "____ hard he works, he never seems to get tired.", "options": ["Whatever", "However", "Whichever", "Whenever"], "answer": "However", "pitfalls": ["误选 Whatever（whatever 不修饰 hard）", "误选 Whichever（whichever 表选择“无论哪一个”）", "误选 Whenever（表时间）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "however + 副词 hard 表示“无论多么努力”，选 B。", "analysis": "【考点】However 引导让步状语从句。 【规则】However + 形容词/副词 + 主语 + 谓语 = No matter how …，表示“无论多么……”。 【步骤】 ① 空格后是副词 hard，需要一个词修饰 hard； ② “无论多么努力”用 However hard； ③ 选 B。 【答案】B。 【口诀】However + 形/副词 = No matter how；Whatever 才作宾语。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-038", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "If I ____ you, I would take an umbrella with me.", "options": ["am", "was", "were", "is"], "answer": "were", "pitfalls": ["误选 was（虚拟语气中 be 动词用 were，不随人称变化）", "误选 am/is（现在时，不用于虚拟）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "对现在情况的虚拟，if 从句谓语用过去式，be 动词一律用 were，选 C。", "analysis": "【考点】与现在事实相反的虚拟语气。 【规则】对现在情况的虚拟： • if 从句：动词过去式（be 动词一律用 were）； • 主句：would/could/should/might + 动词原形。 【分析】句中主句是 I would take…，是对现在的虚拟；从句“如果我是你”要说 If I were you（不用 was），这是固定说法。 【步骤】 ① 主句 would + 动词原形，判断为对现在虚拟； ② 从句 be 动词用 were； ③ 选 C。 【答案】C。 【口诀】对现在虚拟：从句过去式（be 用 were），主句 would do；If I were you 记牢。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-039", "module": "public", "subject": "英语", "chapter": "ch-en-3", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "It was in this small village ____ I spent my childhood.", "options": ["that", "which", "where", "when"], "answer": "that", "pitfalls": ["误选 where（被地点状语误导，以为用 where；强调句固定用 that）", "误选 which", "误选 when"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "强调句结构 It is/was + 被强调部分 + that…，即使强调地点也用 that，选 A。", "analysis": "【考点】强调句型。 【规则】强调句基本结构：It is/was + 被强调部分 + that/who + 其他。强调人时可用 who，强调其他（时间、地点、事物等）一律用 that。 【判别方法】把 It is/was 和 that 去掉，剩下的部分结构和意思仍然完整，就是强调句。 【验证】去掉 It was 和 that 后：In this small village I spent my childhood.（我在这个小村庄度过了童年），句子完整，确认为强调句。 【步骤】 ① 被强调的是地点状语 in this small village； ② 强调句固定用 that，不用 where； ③ 选 A。 【答案】A。 【口诀】强调句 that 通吃，强调人可用 who；去掉 It was…that 句子仍完整。", "steps": []});
  window.STUDY_DATA.questions.push({"id": "mock-enjing-040", "module": "public", "subject": "英语", "chapter": "ch-en-1", "knowledgePoint": "英语语法精编", "type": "single", "typeLabel": "单选", "stem": "____ beautiful the flower is!", "options": ["What", "What a", "How", "How a"], "answer": "How", "pitfalls": ["误选 What（what 修饰名词，如 What a beautiful flower）", "误选 What a（后接名词短语）", "误选 How a（how 不与 a 连用）"], "difficulty": 1, "difficultyLabel": "基础", "source": "mock-migrated", "tags": ["英语语法精编", "迁入"], "hint": "how 修饰形容词/副词；中心词是形容词 beautiful，用 How，选 C。", "analysis": "【考点】感叹句 How/What 的选择。 【规则】 • How + 形容词/副词 + 主语 + 谓语！（how 修饰形容词或副词）； • What (a/an) + 形容词 + 名词 + 主语 + 谓语！（what 修饰名词）。 【对比】 • How beautiful the flower is!（beautiful 是形容词）； • What a beautiful flower it is!（flower 是名词）。 【步骤】 ① 空格后 beautiful 是形容词，主语 the flower、谓语 is； ② 修饰形容词用 How； ③ 选 C。 【答案】C。 【口诀】How 修饰形/副，What 修饰名词；名词可数单数加 a/an。", "steps": []});
